COMMENT ON COLUMN runs.initial_condition IS 'The states at time 0.';
COMMENT ON COLUMN runs.depth IS 'The last time step computed: the horizon.';
COMMENT ON COLUMN runs.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN runs.is_light_cone_exact_cache IS 'Cached IsLightConeExact from the last fresh compile; read by IsLightConeExact while IsCached = 1.';
COMMENT ON COLUMN runs.is_prize_setup_cache IS 'Cached IsPrizeSetup from the last fresh compile; read by IsPrizeSetup while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- TimeSteps: One line of a run: time step t. Width, black count and the center term are aggregated from its cells; cell updates accumulate along the time chain.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS time_steps (
  time_step_id                        TEXT                 PRIMARY KEY          -- <run>-t<time>.
);
ALTER TABLE time_steps ADD COLUMN IF NOT EXISTS run TEXT;                                           -- The run.
ALTER TABLE time_steps ADD COLUMN IF NOT EXISTS time INTEGER;                                       -- Time step t.
ALTER TABLE time_steps ADD COLUMN IF NOT EXISTS previous_step TEXT;                                 -- Time step t - 1; empty at t = 0.
COMMENT ON TABLE time_steps IS 'One line of a run: time step t. Width, black count and the center term are aggregated from its cells; cell updates accumulate along the time chain.';
COMMENT ON COLUMN time_steps.time_step_id IS '<run>-t<time>.';
COMMENT ON COLUMN time_steps.run IS 'The run.';
COMMENT ON COLUMN time_steps.time IS 'Time step t.';
COMMENT ON COLUMN time_steps.previous_step IS 'Time step t - 1; empty at t = 0.';

-- ----------------------------------------------------------------------------
-- Columns: The cells at one position over time, read as a sequence in t. The center column (position 0) is the sequence of center-cell values all three problems are about.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS columns (
  column_id                           TEXT                 PRIMARY KEY          -- <run>-p<position>.
);
ALTER TABLE columns ADD COLUMN IF NOT EXISTS run TEXT;                                              -- The run.
ALTER TABLE columns ADD COLUMN IF NOT EXISTS position INTEGER;                                      -- Position i.
COMMENT ON TABLE columns IS 'The cells at one position over time, read as a sequence in t. The center column (position 0) is the sequence of center-cell values all three problems are about.';
COMMENT ON COLUMN columns.column_id IS '<run>-p<position>.';
COMMENT ON COLUMN columns.run IS 'The run.';
COMMENT ON COLUMN columns.position IS 'Position i.';

-- ----------------------------------------------------------------------------
-- Cells: x(i, t): one cell of a run, inside the light cone |i| <= t <= 64. Its value is the seed at t = 0, otherwise the rule-table output selected by its three parents. Along the column (CenterParent is the previous term) it accumulates the Problem 2 prefix counts and the Problem 1 constant runs.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cells (
  cell_id                             TEXT                 PRIMARY KEY          -- <run>-t<time>p<position>.
);
ALTER TABLE cells ADD COLUMN IF NOT EXISTS run TEXT;                                                -- The run.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS time_step TEXT;                                          -- The line (time step) this cell is on.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS "column" TEXT;                                           -- The column (position) this cell is in.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS seed_cell TEXT;                                          -- At t = 0: the seed cell listed at this position, if any.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS time INTEGER;                                            -- Time step t.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS position INTEGER;                                        -- Position i.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS left_parent TEXT;                                        -- Cell (t-1, i-1); empty outside the cone.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS center_parent TEXT;                                      -- Cell (t-1, i): the previous term of this column; empty outside the cone.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS right_parent TEXT;                                       -- Cell (t-1, i+1); empty outside the cone.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS is_cached INTEGER;                                       -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE cells ADD COLUMN IF NOT EXISTS is_center_cache INTEGER;                                 -- Cached IsCenter from the last fresh compile; read by IsCenter while IsCached = 1.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS prefix_length_cache INTEGER;                             -- Cached PrefixLength from the last fresh compile; read by PrefixLength while IsCached = 1.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS discrepancy_cache INTEGER;                               -- Cached Discrepancy from the last fresh compile; read by Discrepancy while IsCached = 1.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS run_start_cache INTEGER;                                 -- Cached RunStart from the last fresh compile; read by RunStart while IsCached = 1.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS run_length_cache INTEGER;                                -- Cached RunLength from the last fresh compile; read by RunLength while IsCached = 1.
ALTER TABLE cells ADD COLUMN IF NOT EXISTS run_bound_holds_cache INTEGER;                           -- Cached RunBoundHolds from the last fresh compile; read by RunBoundHolds while IsCached = 1.
COMMENT ON TABLE cells IS 'x(i, t): one cell of a run, inside the light cone |i| <= t <= 64. Its value is the seed at t = 0, otherwise the rule-table output selected by its three parents. Along the column (CenterParent is the previous term) it accumulates the Problem 2 prefix counts and the Problem 1 constant runs.';
COMMENT ON COLUMN cells.cell_id IS '<run>-t<time>p<position>.';
COMMENT ON COLUMN cells.run IS 'The run.';
COMMENT ON COLUMN cells.time_step IS 'The line (time step) this cell is on.';
COMMENT ON COLUMN cells."column" IS 'The column (position) this cell is in.';
COMMENT ON COLUMN cells.seed_cell IS 'At t = 0: the seed cell listed at this position, if any.';
COMMENT ON COLUMN cells.time IS 'Time step t.';
COMMENT ON COLUMN cells.position IS 'Position i.';
COMMENT ON COLUMN cells.left_parent IS 'Cell (t-1, i-1); empty outside the cone.';
COMMENT ON COLUMN cells.center_parent IS 'Cell (t-1, i): the previous term of this column; empty outside the cone.';
COMMENT ON COLUMN cells.right_parent IS 'Cell (t-1, i+1); empty outside the cone.';
COMMENT ON COLUMN cells.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN cells.is_center_cache IS 'Cached IsCenter from the last fresh compile; read by IsCenter while IsCached = 1.';
COMMENT ON COLUMN cells.prefix_length_cache IS 'Cached PrefixLength from the last fresh compile; read by PrefixLength while IsCached = 1.';
COMMENT ON COLUMN cells.discrepancy_cache IS 'Cached Discrepancy from the last fresh compile; read by Discrepancy while IsCached = 1.';
COMMENT ON COLUMN cells.run_start_cache IS 'Cached RunStart from the last fresh compile; read by RunStart while IsCached = 1.';
COMMENT ON COLUMN cells.run_length_cache IS 'Cached RunLength from the last fresh compile; read by RunLength while IsCached = 1.';
COMMENT ON COLUMN cells.run_bound_holds_cache IS 'Cached RunBoundHolds from the last fresh compile; read by RunBoundHolds while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- Periods: Candidate periods p >= 1 for Problem 1 (bounded at 24 in the model; unbounded in the problem).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS periods (
  period_id                           TEXT                 PRIMARY KEY          -- p<length>.
);
ALTER TABLE periods ADD COLUMN IF NOT EXISTS length INTEGER;                                        -- The period p.
COMMENT ON TABLE periods IS 'Candidate periods p >= 1 for Problem 1 (bounded at 24 in the model; unbounded in the problem).';
COMMENT ON COLUMN periods.period_id IS 'p<length>.';
COMMENT ON COLUMN periods.length IS 'The period p.';

-- ----------------------------------------------------------------------------
-- PeriodTests: Is this column eventually periodic with this period? A summary of its PeriodicityCandidates: every onset up to the last mismatch is refuted; later onsets survive only because the horizon ends.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS period_tests (
  period_test_id                      TEXT                 PRIMARY KEY          -- <column>-p<period>.
);
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS "column" TEXT;                                    -- The column tested.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS period TEXT;                                      -- The period p.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS is_cached INTEGER;                                -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS last_mismatch_time_cache INTEGER;                 -- Cached LastMismatchTime from the last fresh compile; read by LastMismatchTime while IsCached = 1.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS longest_agreement_streak_cache INTEGER;           -- Cached LongestAgreementStreak from the last fresh compile; read by LongestAgreementStreak while IsCached = 1.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS bounded_refutation_holds_cache INTEGER;           -- Cached BoundedRefutationHolds from the last fresh compile; read by BoundedRefutationHolds while IsCached = 1.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS window_count_cache INTEGER;                       -- Cached WindowCount from the last fresh compile; read by WindowCount while IsCached = 1.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS window_failure_count_cache INTEGER;               -- Cached WindowFailureCount from the last fresh compile; read by WindowFailureCount while IsCached = 1.
ALTER TABLE period_tests ADD COLUMN IF NOT EXISTS windows_hold_cache INTEGER;                       -- Cached WindowsHold from the last fresh compile; read by WindowsHold while IsCached = 1.
COMMENT ON TABLE period_tests IS 'Is this column eventually periodic with this period? A summary of its PeriodicityCandidates: every onset up to the last mismatch is refuted; later onsets survive only because the horizon ends.';
COMMENT ON COLUMN period_tests.period_test_id IS '<column>-p<period>.';
COMMENT ON COLUMN period_tests."column" IS 'The column tested.';
COMMENT ON COLUMN period_tests.period IS 'The period p.';
COMMENT ON COLUMN period_tests.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN period_tests.last_mismatch_time_cache IS 'Cached LastMismatchTime from the last fresh compile; read by LastMismatchTime while IsCached = 1.';
COMMENT ON COLUMN period_tests.longest_agreement_streak_cache IS 'Cached LongestAgreementStreak from the last fresh compile; read by LongestAgreementStreak while IsCached = 1.';
COMMENT ON COLUMN period_tests.bounded_refutation_holds_cache IS 'Cached BoundedRefutationHolds from the last fresh compile; read by BoundedRefutationHolds while IsCached = 1.';
COMMENT ON COLUMN period_tests.window_count_cache IS 'Cached WindowCount from the last fresh compile; read by WindowCount while IsCached = 1.';
COMMENT ON COLUMN period_tests.window_failure_count_cache IS 'Cached WindowFailureCount from the last fresh compile; read by WindowFailureCount while IsCached = 1.';
COMMENT ON COLUMN period_tests.windows_hold_cache IS 'Cached WindowsHold from the last fresh compile; read by WindowsHold while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- PeriodicityCandidates: The hypothesis 'column i is periodic with period p from onset T' (Problem 1 quantifies over these (p, T)). Each row is also the comparison x(i, T) vs x(i, T + p); the chain to T + 1 finds the first mismatch at or after T: the witness that refutes the candidate.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS periodicity_candidates (
  periodicity_candidate_id            TEXT                 PRIMARY KEY          -- <period test>-T<onset>.
);
ALTER TABLE periodicity_candidates ADD COLUMN IF NOT EXISTS period_test TEXT;                       -- The column and period.
ALTER TABLE periodicity_candidates ADD COLUMN IF NOT EXISTS onset INTEGER;                          -- The onset T.
ALTER TABLE periodicity_candidates ADD COLUMN IF NOT EXISTS earlier_cell TEXT;                      -- x(i, T); empty before the light cone reaches the column (white).
ALTER TABLE periodicity_candidates ADD COLUMN IF NOT EXISTS later_cell TEXT;                        -- x(i, T + p).
ALTER TABLE periodicity_candidates ADD COLUMN IF NOT EXISTS next_candidate TEXT;                    -- The candidate with onset T + 1; empty at the last onset.
COMMENT ON TABLE periodicity_candidates IS 'The hypothesis ''column i is periodic with period p from onset T'' (Problem 1 quantifies over these (p, T)). Each row is also the comparison x(i, T) vs x(i, T + p); the chain to T + 1 finds the first mismatch at or after T: the witness that refutes the candidate.';
COMMENT ON COLUMN periodicity_candidates.periodicity_candidate_id IS '<period test>-T<onset>.';
COMMENT ON COLUMN periodicity_candidates.period_test IS 'The column and period.';
COMMENT ON COLUMN periodicity_candidates.onset IS 'The onset T.';
COMMENT ON COLUMN periodicity_candidates.earlier_cell IS 'x(i, T); empty before the light cone reaches the column (white).';
COMMENT ON COLUMN periodicity_candidates.later_cell IS 'x(i, T + p).';
COMMENT ON COLUMN periodicity_candidates.next_candidate IS 'The candidate with onset T + 1; empty at the last onset.';

-- ----------------------------------------------------------------------------
-- MismatchWindows: Theorem C for one (T, p): some i in {0, 1} and t in [T, 2T + p] have x(i, t) != x(i, t + p). Only windows that end inside the horizon are rows.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS mismatch_windows (
  mismatch_window_id                  TEXT                 PRIMARY KEY          -- tc-p<period>-T<onset>.
);
ALTER TABLE mismatch_windows ADD COLUMN IF NOT EXISTS onset INTEGER;                                -- T.
ALTER TABLE mismatch_windows ADD COLUMN IF NOT EXISTS period TEXT;                                  -- p.
ALTER TABLE mismatch_windows ADD COLUMN IF NOT EXISTS center_test TEXT;                             -- The center column test for p (for the roll-up).
ALTER TABLE mismatch_windows ADD COLUMN IF NOT EXISTS center_candidate TEXT;                        -- Column 0 with period p from onset T.
ALTER TABLE mismatch_windows ADD COLUMN IF NOT EXISTS neighbor_candidate TEXT;                      -- Column 1 with period p from onset T.
COMMENT ON TABLE mismatch_windows IS 'Theorem C for one (T, p): some i in {0, 1} and t in [T, 2T + p] have x(i, t) != x(i, t + p). Only windows that end inside the horizon are rows.';
COMMENT ON COLUMN mismatch_windows.mismatch_window_id IS 'tc-p<period>-T<onset>.';
COMMENT ON COLUMN mismatch_windows.onset IS 'T.';
COMMENT ON COLUMN mismatch_windows.period IS 'p.';
COMMENT ON COLUMN mismatch_windows.center_test IS 'The center column test for p (for the roll-up).';
COMMENT ON COLUMN mismatch_windows.center_candidate IS 'Column 0 with period p from onset T.';
COMMENT ON COLUMN mismatch_windows.neighbor_candidate IS 'Column 1 with period p from onset T.';

-- ----------------------------------------------------------------------------
-- LeftConsistencyChecks: TX at one time step of the real center: when c(t) = 1 the rule at column 0 forces c(t + 1) = NOT x(-1, t), so the center is decided by its own past through the left half. After a 0 the left half says nothing.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS left_consistency_checks (
  left_consistency_check_id           TEXT                 PRIMARY KEY          -- <run>-tx-t<time>.
);
ALTER TABLE left_consistency_checks ADD COLUMN IF NOT EXISTS time INTEGER;                          -- t.
ALTER TABLE left_consistency_checks ADD COLUMN IF NOT EXISTS term TEXT;                             -- c(t).
ALTER TABLE left_consistency_checks ADD COLUMN IF NOT EXISTS next_term TEXT;                        -- c(t + 1).
ALTER TABLE left_consistency_checks ADD COLUMN IF NOT EXISTS left_cell TEXT;                        -- x(-1, t); empty at t = 0 (white).
ALTER TABLE left_consistency_checks ADD COLUMN IF NOT EXISTS is_cached INTEGER;                     -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE left_consistency_checks ADD COLUMN IF NOT EXISTS is_consistent_cache INTEGER;           -- Cached IsConsistent from the last fresh compile; read by IsConsistent while IsCached = 1.
COMMENT ON TABLE left_consistency_checks IS 'TX at one time step of the real center: when c(t) = 1 the rule at column 0 forces c(t + 1) = NOT x(-1, t), so the center is decided by its own past through the left half. After a 0 the left half says nothing.';
COMMENT ON COLUMN left_consistency_checks.left_consistency_check_id IS '<run>-tx-t<time>.';
COMMENT ON COLUMN left_consistency_checks.time IS 't.';
COMMENT ON COLUMN left_consistency_checks.term IS 'c(t).';
COMMENT ON COLUMN left_consistency_checks.next_term IS 'c(t + 1).';
COMMENT ON COLUMN left_consistency_checks.left_cell IS 'x(-1, t); empty at t = 0 (white).';
COMMENT ON COLUMN left_consistency_checks.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN left_consistency_checks.is_consistent_cache IS 'Cached IsConsistent from the last fresh compile; read by IsConsistent while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- PeriodicWords: A finite word a; the tail a a a ... is what an eventually periodic center would repeat. Its least period, constancy and B9 membership are computed from its letters.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS periodic_words (
  periodic_word_id                    TEXT                 PRIMARY KEY          -- w<letters>.
);
ALTER TABLE periodic_words ADD COLUMN IF NOT EXISTS length INTEGER;                                 -- Number of letters |a|.
COMMENT ON TABLE periodic_words IS 'A finite word a; the tail a a a ... is what an eventually periodic center would repeat. Its least period, constancy and B9 membership are computed from its letters.';
COMMENT ON COLUMN periodic_words.periodic_word_id IS 'w<letters>.';
COMMENT ON COLUMN periodic_words.length IS 'Number of letters |a|.';

-- ----------------------------------------------------------------------------
-- WordLetters: One letter a[k] of a word.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS word_letters (
  word_letter_id                      TEXT                 PRIMARY KEY          -- <word>-k<index>.
);
ALTER TABLE word_letters ADD COLUMN IF NOT EXISTS periodic_word TEXT;                               -- The word.
ALTER TABLE word_letters ADD COLUMN IF NOT EXISTS letter_index INTEGER;                             -- k, from 0.
ALTER TABLE word_letters ADD COLUMN IF NOT EXISTS letter_bit INTEGER;                               -- a[k].
COMMENT ON TABLE word_letters IS 'One letter a[k] of a word.';
COMMENT ON COLUMN word_letters.word_letter_id IS '<word>-k<index>.';
COMMENT ON COLUMN word_letters.periodic_word IS 'The word.';
COMMENT ON COLUMN word_letters.letter_index IS 'k, from 0.';
COMMENT ON COLUMN word_letters.letter_bit IS 'a[k].';

-- ----------------------------------------------------------------------------
-- WordShifts: A rotation of a word by d positions; a symmetry when every letter matches its rotated partner.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS word_shifts (
  word_shift_id                       TEXT                 PRIMARY KEY          -- <word>-d<shift>.
);
ALTER TABLE word_shifts ADD COLUMN IF NOT EXISTS periodic_word TEXT;                                -- The word.
ALTER TABLE word_shifts ADD COLUMN IF NOT EXISTS shift INTEGER;                                     -- d, 1 .. |a|.
COMMENT ON TABLE word_shifts IS 'A rotation of a word by d positions; a symmetry when every letter matches its rotated partner.';
COMMENT ON COLUMN word_shifts.word_shift_id IS '<word>-d<shift>.';
COMMENT ON COLUMN word_shifts.periodic_word IS 'The word.';
COMMENT ON COLUMN word_shifts.shift IS 'd, 1 .. |a|.';

-- ----------------------------------------------------------------------------
-- WordShiftChecks: One letter against its rotated partner: a[k] vs a[(k + d) mod |a|].
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS word_shift_checks (
  word_shift_check_id                 TEXT                 PRIMARY KEY          -- <shift>-k<index>.
);
ALTER TABLE word_shift_checks ADD COLUMN IF NOT EXISTS word_shift TEXT;                             -- The rotation.
ALTER TABLE word_shift_checks ADD COLUMN IF NOT EXISTS letter TEXT;                                 -- a[k].
ALTER TABLE word_shift_checks ADD COLUMN IF NOT EXISTS partner_letter TEXT;                         -- a[(k + d) mod |a|].
COMMENT ON TABLE word_shift_checks IS 'One letter against its rotated partner: a[k] vs a[(k + d) mod |a|].';
COMMENT ON COLUMN word_shift_checks.word_shift_check_id IS '<shift>-k<index>.';
COMMENT ON COLUMN word_shift_checks.word_shift IS 'The rotation.';
COMMENT ON COLUMN word_shift_checks.letter IS 'a[k].';
COMMENT ON COLUMN word_shift_checks.partner_letter IS 'a[(k + d) mod |a|].';

-- ----------------------------------------------------------------------------
-- TailCandidates: The real center up to onset T, then the tail a a a ... from T: the center an eventual a-periodicity from T would have. TX says the real center is left-consistent; B9 says no left-consistent sequence ends in a nonconstant periodic tail, so every candidate must fail a one-time check. The kill uses only the real prefix and the rule, never the real center after T.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tail_candidates (
  tail_candidate_id                   TEXT                 PRIMARY KEY          -- tail-<word>-T<onset>.
);
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS run TEXT;                                      -- The run whose prefix is used.
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS periodic_word TEXT;                            -- The tail word a.
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS onset INTEGER;                                 -- T: the first time step of the tail.
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS horizon INTEGER;                               -- The last time step checked (onset + 12).
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS is_cached INTEGER;                             -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS kill_time_cache INTEGER;                       -- Cached KillTime from the last fresh compile; read by KillTime while IsCached = 1.
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS is_killed_cache INTEGER;                       -- Cached IsKilled from the last fresh compile; read by IsKilled while IsCached = 1.
ALTER TABLE tail_candidates ADD COLUMN IF NOT EXISTS kill_excess_cache INTEGER;                     -- Cached KillExcess from the last fresh compile; read by KillExcess while IsCached = 1.
COMMENT ON TABLE tail_candidates IS 'The real center up to onset T, then the tail a a a ... from T: the center an eventual a-periodicity from T would have. TX says the real center is left-consistent; B9 says no left-consistent sequence ends in a nonconstant periodic tail, so every candidate must fail a one-time check. The kill uses only the real prefix and the rule, never the real center after T.';
COMMENT ON COLUMN tail_candidates.tail_candidate_id IS 'tail-<word>-T<onset>.';
COMMENT ON COLUMN tail_candidates.run IS 'The run whose prefix is used.';
COMMENT ON COLUMN tail_candidates.periodic_word IS 'The tail word a.';
COMMENT ON COLUMN tail_candidates.onset IS 'T: the first time step of the tail.';
COMMENT ON COLUMN tail_candidates.horizon IS 'The last time step checked (onset + 12).';
COMMENT ON COLUMN tail_candidates.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN tail_candidates.kill_time_cache IS 'Cached KillTime from the last fresh compile; read by KillTime while IsCached = 1.';
COMMENT ON COLUMN tail_candidates.is_killed_cache IS 'Cached IsKilled from the last fresh compile; read by IsKilled while IsCached = 1.';
COMMENT ON COLUMN tail_candidates.kill_excess_cache IS 'Cached KillExcess from the last fresh compile; read by KillExcess while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- TailCenterTerms: c'(t) of a tail candidate: the real center before the onset, the tail word's letter a[(t - T) mod |a|] from it.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tail_center_terms (
  tail_center_term_id                 TEXT                 PRIMARY KEY          -- <candidate>-c<time>.
);
ALTER TABLE tail_center_terms ADD COLUMN IF NOT EXISTS tail_candidate TEXT;                         -- The candidate.
ALTER TABLE tail_center_terms ADD COLUMN IF NOT EXISTS time INTEGER;                                -- t.
ALTER TABLE tail_center_terms ADD COLUMN IF NOT EXISTS real_cell TEXT;                              -- Before the onset: c(t).
ALTER TABLE tail_center_terms ADD COLUMN IF NOT EXISTS letter TEXT;                                 -- From the onset: the letter a[(t - T) mod |a|].
COMMENT ON TABLE tail_center_terms IS 'c''(t) of a tail candidate: the real center before the onset, the tail word''s letter a[(t - T) mod |a|] from it.';
COMMENT ON COLUMN tail_center_terms.tail_center_term_id IS '<candidate>-c<time>.';
COMMENT ON COLUMN tail_center_terms.tail_candidate IS 'The candidate.';
COMMENT ON COLUMN tail_center_terms.time IS 't.';
COMMENT ON COLUMN tail_center_terms.real_cell IS 'Before the onset: c(t).';
COMMENT ON COLUMN tail_center_terms.letter IS 'From the onset: the letter a[(t - T) mod |a|].';

-- ----------------------------------------------------------------------------
-- TailCells: x'(i, t), i <= -1, of a tail candidate: the left half driven by c'. At the onset it equals the real left half (TX: the left half depends only on the center's past); after it, Rule 30 with c' as the right boundary. Only cells that can reach x'(-1, t) by the horizon are rows.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tail_cells (
  tail_cell_id                        TEXT                 PRIMARY KEY          -- <candidate>-<time><position>.
);
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS tail_candidate TEXT;                                -- The candidate.
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS time INTEGER;                                       -- t.
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS position INTEGER;                                   -- i <= -1.
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS real_cell TEXT;                                     -- At the onset: the real cell x(i, T).
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS left_parent TEXT;                                   -- x'(i - 1, t - 1); empty outside the cone (white).
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS center_parent TEXT;                                 -- x'(i, t - 1).
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS right_parent TEXT;                                  -- x'(i + 1, t - 1), for i <= -2.
ALTER TABLE tail_cells ADD COLUMN IF NOT EXISTS center_term TEXT;                                   -- c'(t - 1), the right parent of column -1.
COMMENT ON TABLE tail_cells IS 'x''(i, t), i <= -1, of a tail candidate: the left half driven by c''. At the onset it equals the real left half (TX: the left half depends only on the center''s past); after it, Rule 30 with c'' as the right boundary. Only cells that can reach x''(-1, t) by the horizon are rows.';
COMMENT ON COLUMN tail_cells.tail_cell_id IS '<candidate>-<time><position>.';
COMMENT ON COLUMN tail_cells.tail_candidate IS 'The candidate.';
COMMENT ON COLUMN tail_cells.time IS 't.';
COMMENT ON COLUMN tail_cells.position IS 'i <= -1.';
COMMENT ON COLUMN tail_cells.real_cell IS 'At the onset: the real cell x(i, T).';
COMMENT ON COLUMN tail_cells.left_parent IS 'x''(i - 1, t - 1); empty outside the cone (white).';
COMMENT ON COLUMN tail_cells.center_parent IS 'x''(i, t - 1).';
COMMENT ON COLUMN tail_cells.right_parent IS 'x''(i + 1, t - 1), for i <= -2.';
COMMENT ON COLUMN tail_cells.center_term IS 'c''(t - 1), the right parent of column -1.';

-- ----------------------------------------------------------------------------
-- TailChecks: The one-time check at t of a tail candidate: when c'(t) = 1, left-consistency requires c'(t + 1) = NOT x'(-1, t). The chain to t + 1 finds the first violation: the kill.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tail_checks (
  tail_check_id                       TEXT                 PRIMARY KEY          -- <candidate>-x<time>.
);
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS tail_candidate TEXT;                               -- The candidate.
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS time INTEGER;                                      -- t.
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS term TEXT;                                         -- c'(t).
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS next_term TEXT;                                    -- c'(t + 1).
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS real_left_cell TEXT;                               -- Before the onset: x(-1, t) (empty at t = 0, white).
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS tail_left_cell TEXT;                               -- From the onset: x'(-1, t).
ALTER TABLE tail_checks ADD COLUMN IF NOT EXISTS next_check TEXT;                                   -- The check at t + 1; empty at the horizon.
COMMENT ON TABLE tail_checks IS 'The one-time check at t of a tail candidate: when c''(t) = 1, left-consistency requires c''(t + 1) = NOT x''(-1, t). The chain to t + 1 finds the first violation: the kill.';
COMMENT ON COLUMN tail_checks.tail_check_id IS '<candidate>-x<time>.';
COMMENT ON COLUMN tail_checks.tail_candidate IS 'The candidate.';
COMMENT ON COLUMN tail_checks.time IS 't.';
COMMENT ON COLUMN tail_checks.term IS 'c''(t).';
COMMENT ON COLUMN tail_checks.next_term IS 'c''(t + 1).';
COMMENT ON COLUMN tail_checks.real_left_cell IS 'Before the onset: x(-1, t) (empty at t = 0, white).';
COMMENT ON COLUMN tail_checks.tail_left_cell IS 'From the onset: x''(-1, t).';
COMMENT ON COLUMN tail_checks.next_check IS 'The check at t + 1; empty at the horizon.';

-- ----------------------------------------------------------------------------
-- Diagonals: A diagonal of the cone read as a sequence in t: right side y_k(t) = x(t - k, t), left side w_k(t) = x(k - t, t) (k = 0 is the edge). Before the cone reaches it a diagonal is white.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS diagonals (
  diagonal_id                         TEXT                 PRIMARY KEY          -- <side>-k<offset>.
);
ALTER TABLE diagonals ADD COLUMN IF NOT EXISTS side TEXT;                                           -- right (y_k) or left (w_k).
ALTER TABLE diagonals ADD COLUMN IF NOT EXISTS "offset" INTEGER;                                    -- k.
ALTER TABLE diagonals ADD COLUMN IF NOT EXISTS previous_diagonal TEXT;                              -- The diagonal k - 1 on the same side; empty at k = 0.
ALTER TABLE diagonals ADD COLUMN IF NOT EXISTS opposite_diagonal TEXT;                              -- For a left diagonal w_k: the right diagonal y_k (one direction only).
ALTER TABLE diagonals ADD COLUMN IF NOT EXISTS depth INTEGER;                                       -- The horizon (the run depth).
COMMENT ON TABLE diagonals IS 'A diagonal of the cone read as a sequence in t: right side y_k(t) = x(t - k, t), left side w_k(t) = x(k - t, t) (k = 0 is the edge). Before the cone reaches it a diagonal is white.';
COMMENT ON COLUMN diagonals.diagonal_id IS '<side>-k<offset>.';
COMMENT ON COLUMN diagonals.side IS 'right (y_k) or left (w_k).';
COMMENT ON COLUMN diagonals."offset" IS 'k.';
COMMENT ON COLUMN diagonals.previous_diagonal IS 'The diagonal k - 1 on the same side; empty at k = 0.';
COMMENT ON COLUMN diagonals.opposite_diagonal IS 'For a left diagonal w_k: the right diagonal y_k (one direction only).';
COMMENT ON COLUMN diagonals.depth IS 'The horizon (the run depth).';

-- ----------------------------------------------------------------------------
-- DiagonalPeriodTests: Is the dyadic d a period of the diagonal, from t = 0 (pure) or from some onset (eventual)?
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS diagonal_period_tests (
  diagonal_period_test_id             TEXT                 PRIMARY KEY          -- <diagonal>-d<period>.
);
ALTER TABLE diagonal_period_tests ADD COLUMN IF NOT EXISTS diagonal TEXT;                           -- The diagonal.
ALTER TABLE diagonal_period_tests ADD COLUMN IF NOT EXISTS period INTEGER;                          -- d, a power of two.
ALTER TABLE diagonal_period_tests ADD COLUMN IF NOT EXISTS half_cell TEXT;                          -- The cell of the diagonal at t = d / 2 (empty before the cone: white).
ALTER TABLE diagonal_period_tests ADD COLUMN IF NOT EXISTS is_cached INTEGER;                       -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE diagonal_period_tests ADD COLUMN IF NOT EXISTS is_pure_period_cache INTEGER;            -- Cached IsPurePeriod from the last fresh compile; read by IsPurePeriod while IsCached = 1.
COMMENT ON TABLE diagonal_period_tests IS 'Is the dyadic d a period of the diagonal, from t = 0 (pure) or from some onset (eventual)?';
COMMENT ON COLUMN diagonal_period_tests.diagonal_period_test_id IS '<diagonal>-d<period>.';
COMMENT ON COLUMN diagonal_period_tests.diagonal IS 'The diagonal.';
COMMENT ON COLUMN diagonal_period_tests.period IS 'd, a power of two.';
COMMENT ON COLUMN diagonal_period_tests.half_cell IS 'The cell of the diagonal at t = d / 2 (empty before the cone: white).';
COMMENT ON COLUMN diagonal_period_tests.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN diagonal_period_tests.is_pure_period_cache IS 'Cached IsPurePeriod from the last fresh compile; read by IsPurePeriod while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- DiagonalPeriodChecks: One comparison of a diagonal period test: the diagonal at t against t + d.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS diagonal_period_checks (
  diagonal_period_check_id            TEXT                 PRIMARY KEY          -- <test>-t<time>.
);
ALTER TABLE diagonal_period_checks ADD COLUMN IF NOT EXISTS diagonal_period_test TEXT;              -- The test.
ALTER TABLE diagonal_period_checks ADD COLUMN IF NOT EXISTS time INTEGER;                           -- t.
ALTER TABLE diagonal_period_checks ADD COLUMN IF NOT EXISTS earlier_cell TEXT;                      -- The diagonal at t (empty before the cone: white).
ALTER TABLE diagonal_period_checks ADD COLUMN IF NOT EXISTS later_cell TEXT;                        -- The diagonal at t + d.
COMMENT ON TABLE diagonal_period_checks IS 'One comparison of a diagonal period test: the diagonal at t against t + d.';
COMMENT ON COLUMN diagonal_period_checks.diagonal_period_check_id IS '<test>-t<time>.';
COMMENT ON COLUMN diagonal_period_checks.diagonal_period_test IS 'The test.';
COMMENT ON COLUMN diagonal_period_checks.time IS 't.';
COMMENT ON COLUMN diagonal_period_checks.earlier_cell IS 'The diagonal at t (empty before the cone: white).';
COMMENT ON COLUMN diagonal_period_checks.later_cell IS 'The diagonal at t + d.';

-- ----------------------------------------------------------------------------
-- DiagonalFacts: One fact a predicate states about one diagonal, decided from the diagonal's computed periods and cells.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS diagonal_facts (
  diagonal_fact_id                    TEXT                 PRIMARY KEY          -- <fact>-<diagonal>.
);
ALTER TABLE diagonal_facts ADD COLUMN IF NOT EXISTS fact TEXT;                                      -- Which fact: all-ones: every cone cell on the edge is black; first-one-at-half: first black cell at t = ceil(k/2), and P_k exceeds that time; balanced: exactly half the cells of one least period are black; doubles: P_k = 2 P_{k-1}; nondecreasing: P_k >= P_{k-1}; repeat-or-double: P_k is P_{k-1} or 2 P_{k-1}; no-triple-double: not (eps_k = eps_{k-1} = eps_{k-2} = 1); half-period-one: y_k(P_k / 2) = 1; eventually-dyadic: w_k has a dyadic eventual period <= min(2^k, 8) inside the horizon; parity-after-doubling: if eps_{k-1} = 1 then eps_k = ones of y_{k-2} per period mod 2; parity-always: eps_k = ones of y_{k-2} per period mod 2; left-half-speed: Pw_k^2 <= P_k (log2 Pw_k <= log2 P_k / 2).
ALTER TABLE diagonal_facts ADD COLUMN IF NOT EXISTS diagonal TEXT;                                  -- The diagonal.
ALTER TABLE diagonal_facts ADD COLUMN IF NOT EXISTS is_cached INTEGER;                              -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE diagonal_facts ADD COLUMN IF NOT EXISTS holds_cache INTEGER;                            -- Cached Holds from the last fresh compile; read by Holds while IsCached = 1.
ALTER TABLE diagonal_facts ADD COLUMN IF NOT EXISTS is_decided_cache INTEGER;                       -- Cached IsDecided from the last fresh compile; read by IsDecided while IsCached = 1.
COMMENT ON TABLE diagonal_facts IS 'One fact a predicate states about one diagonal, decided from the diagonal''s computed periods and cells.';
COMMENT ON COLUMN diagonal_facts.diagonal_fact_id IS '<fact>-<diagonal>.';
COMMENT ON COLUMN diagonal_facts.fact IS 'Which fact: all-ones: every cone cell on the edge is black; first-one-at-half: first black cell at t = ceil(k/2), and P_k exceeds that time; balanced: exactly half the cells of one least period are black; doubles: P_k = 2 P_{k-1}; nondecreasing: P_k >= P_{k-1}; repeat-or-double: P_k is P_{k-1} or 2 P_{k-1}; no-triple-double: not (eps_k = eps_{k-1} = eps_{k-2} = 1); half-period-one: y_k(P_k / 2) = 1; eventually-dyadic: w_k has a dyadic eventual period <= min(2^k, 8) inside the horizon; parity-after-doubling: if eps_{k-1} = 1 then eps_k = ones of y_{k-2} per period mod 2; parity-always: eps_k = ones of y_{k-2} per period mod 2; left-half-speed: Pw_k^2 <= P_k (log2 Pw_k <= log2 P_k / 2).';
COMMENT ON COLUMN diagonal_facts.diagonal IS 'The diagonal.';
COMMENT ON COLUMN diagonal_facts.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN diagonal_facts.holds_cache IS 'Cached Holds from the last fresh compile; read by Holds while IsCached = 1.';
COMMENT ON COLUMN diagonal_facts.is_decided_cache IS 'Cached IsDecided from the last fresh compile; read by IsDecided while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- Tolerances: Margins epsilon around 1/2 for Problem 2. The limit is 1/2 exactly when, for every epsilon, excursions eventually stop.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tolerances (
  tolerance_id                        TEXT                 PRIMARY KEY          -- eps-<numerator>-<denominator>.
);
ALTER TABLE tolerances ADD COLUMN IF NOT EXISTS epsilon_numerator INTEGER;                          -- Numerator of the margin.
ALTER TABLE tolerances ADD COLUMN IF NOT EXISTS epsilon_denominator INTEGER;                        -- Denominator of the margin. Exact integers, because a float margin and a NUMERIC margin disagree at exact boundaries (docs/toolchain-gaps.md gap 9).
ALTER TABLE tolerances ADD COLUMN IF NOT EXISTS is_cached INTEGER;                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE tolerances ADD COLUMN IF NOT EXISTS last_excursion_time_cache INTEGER;                  -- Cached LastExcursionTime from the last fresh compile; read by LastExcursionTime while IsCached = 1.
ALTER TABLE tolerances ADD COLUMN IF NOT EXISTS settled_at_horizon_cache INTEGER;                   -- Cached SettledAtHorizon from the last fresh compile; read by SettledAtHorizon while IsCached = 1.
COMMENT ON TABLE tolerances IS 'Margins epsilon around 1/2 for Problem 2. The limit is 1/2 exactly when, for every epsilon, excursions eventually stop.';
COMMENT ON COLUMN tolerances.tolerance_id IS 'eps-<numerator>-<denominator>.';
COMMENT ON COLUMN tolerances.epsilon_numerator IS 'Numerator of the margin.';
COMMENT ON COLUMN tolerances.epsilon_denominator IS 'Denominator of the margin. Exact integers, because a float margin and a NUMERIC margin disagree at exact boundaries (docs/toolchain-gaps.md gap 9).';
COMMENT ON COLUMN tolerances.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN tolerances.last_excursion_time_cache IS 'Cached LastExcursionTime from the last fresh compile; read by LastExcursionTime while IsCached = 1.';
COMMENT ON COLUMN tolerances.settled_at_horizon_cache IS 'Cached SettledAtHorizon from the last fresh compile; read by SettledAtHorizon while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- ToleranceChecks: One prefix of the center column against one tolerance: is its density within epsilon of 1/2?
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tolerance_checks (
  tolerance_check_id                  TEXT                 PRIMARY KEY          -- <tolerance>-t<time>.
);
ALTER TABLE tolerance_checks ADD COLUMN IF NOT EXISTS tolerance TEXT;                               -- The margin.
ALTER TABLE tolerance_checks ADD COLUMN IF NOT EXISTS cell TEXT;                                    -- The center cell ending the prefix.
COMMENT ON TABLE tolerance_checks IS 'One prefix of the center column against one tolerance: is its density within epsilon of 1/2?';
COMMENT ON COLUMN tolerance_checks.tolerance_check_id IS '<tolerance>-t<time>.';
COMMENT ON COLUMN tolerance_checks.tolerance IS 'The margin.';
COMMENT ON COLUMN tolerance_checks.cell IS 'The center cell ending the prefix.';

-- ----------------------------------------------------------------------------
-- ColorCounts: How often each color occurs in each column ("does each color of cell occur on average equally often").
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS color_counts (
  color_count_id                      TEXT                 PRIMARY KEY          -- <column>-<color>.
);
ALTER TABLE color_counts ADD COLUMN IF NOT EXISTS "column" TEXT;                                    -- The column.
ALTER TABLE color_counts ADD COLUMN IF NOT EXISTS cell_state TEXT;                                  -- The color.
COMMENT ON TABLE color_counts IS 'How often each color occurs in each column ("does each color of cell occur on average equally often").';
COMMENT ON COLUMN color_counts.color_count_id IS '<column>-<color>.';
COMMENT ON COLUMN color_counts."column" IS 'The column.';
COMMENT ON COLUMN color_counts.cell_state IS 'The color.';

-- ----------------------------------------------------------------------------
-- MachineModels: What one step of computational effort is: the cost model. Problem 3 needs one fixed; universality relates them only up to simulation overhead.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS machine_models (
  machine_model_id                    TEXT                 PRIMARY KEY          -- Name of the model.
);
ALTER TABLE machine_models ADD COLUMN IF NOT EXISTS step_meaning TEXT;                              -- What one unit of effort counts.
ALTER TABLE machine_models ADD COLUMN IF NOT EXISTS input_encoding TEXT;                            -- How n is given to the machine.
COMMENT ON TABLE machine_models IS 'What one step of computational effort is: the cost model. Problem 3 needs one fixed; universality relates them only up to simulation overhead.';
COMMENT ON COLUMN machine_models.machine_model_id IS 'Name of the model.';
COMMENT ON COLUMN machine_models.step_meaning IS 'What one unit of effort counts.';
COMMENT ON COLUMN machine_models.input_encoding IS 'How n is given to the machine.';

-- ----------------------------------------------------------------------------
-- Algorithms: A way of computing c(n) on a machine model. An algorithm that stores the answer is not admissible. Problem 3 asks whether every admissible algorithm's effort ratio effort/n is unbounded. Light-cone simulation costs O(n²) cell updates; beating O(n²) would be a partial result.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS algorithms (
  algorithm_id                        TEXT                 PRIMARY KEY          -- Name of the algorithm.
);
ALTER TABLE algorithms ADD COLUMN IF NOT EXISTS machine_model TEXT;                                 -- The machine model its effort is counted in.
ALTER TABLE algorithms ADD COLUMN IF NOT EXISTS effort_rule TEXT;                                   -- How its effort for n is counted: cone-updates (simulate the light cone) or table-read (one read).
ALTER TABLE algorithms ADD COLUMN IF NOT EXISTS stores_answer INTEGER;                              -- 1 when the machine contains the sequence itself.
ALTER TABLE algorithms ADD COLUMN IF NOT EXISTS is_cached INTEGER;                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE algorithms ADD COLUMN IF NOT EXISTS effort_holds_cache INTEGER;                         -- Cached EffortHolds from the last fresh compile; read by EffortHolds while IsCached = 1.
COMMENT ON TABLE algorithms IS 'A way of computing c(n) on a machine model. An algorithm that stores the answer is not admissible. Problem 3 asks whether every admissible algorithm''s effort ratio effort/n is unbounded. Light-cone simulation costs O(n²) cell updates; beating O(n²) would be a partial result.';
COMMENT ON COLUMN algorithms.algorithm_id IS 'Name of the algorithm.';
COMMENT ON COLUMN algorithms.machine_model IS 'The machine model its effort is counted in.';
COMMENT ON COLUMN algorithms.effort_rule IS 'How its effort for n is counted: cone-updates (simulate the light cone) or table-read (one read).';
COMMENT ON COLUMN algorithms.stores_answer IS '1 when the machine contains the sequence itself.';
COMMENT ON COLUMN algorithms.is_cached IS '1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).';
COMMENT ON COLUMN algorithms.effort_holds_cache IS 'Cached EffortHolds from the last fresh compile; read by EffortHolds while IsCached = 1.';

-- ----------------------------------------------------------------------------
-- Computations: machine[m][n] = {v, t}: one algorithm computing c(n), with its output value and effort.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS computations (
  computation_id                      TEXT                 PRIMARY KEY          -- <algorithm>-n<n>.
);
ALTER TABLE computations ADD COLUMN IF NOT EXISTS algorithm TEXT;                                   -- The algorithm m.
ALTER TABLE computations ADD COLUMN IF NOT EXISTS time_step TEXT;                                   -- The target time step n.
COMMENT ON TABLE computations IS 'machine[m][n] = {v, t}: one algorithm computing c(n), with its output value and effort.';
COMMENT ON COLUMN computations.computation_id IS '<algorithm>-n<n>.';
COMMENT ON COLUMN computations.algorithm IS 'The algorithm m.';
COMMENT ON COLUMN computations.time_step IS 'The target time step n.';

-- ----------------------------------------------------------------------------
-- Variables: The variables the predicates quantify over, the table whose rows are their values in the model, and whether their domain is infinite in the problem.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS variables (
  variable_id                         TEXT                 PRIMARY KEY          -- Name of the variable.
);
ALTER TABLE variables ADD COLUMN IF NOT EXISTS symbol TEXT;                                         -- How the problem writes it.
ALTER TABLE variables ADD COLUMN IF NOT EXISTS meaning TEXT;                                        -- What it ranges over.
ALTER TABLE variables ADD COLUMN IF NOT EXISTS domain_table TEXT;                                   -- The table whose rows are its values in the model (finite there).
ALTER TABLE variables ADD COLUMN IF NOT EXISTS is_unbounded_in_problem INTEGER;                     -- 1 when its domain in the problem is infinite.
COMMENT ON TABLE variables IS 'The variables the predicates quantify over, the table whose rows are their values in the model, and whether their domain is infinite in the problem.';
COMMENT ON COLUMN variables.variable_id IS 'Name of the variable.';
COMMENT ON COLUMN variables.symbol IS 'How the problem writes it.';
COMMENT ON COLUMN variables.meaning IS 'What it ranges over.';
COMMENT ON COLUMN variables.domain_table IS 'The table whose rows are its values in the model (finite there).';
COMMENT ON COLUMN variables.is_unbounded_in_problem IS '1 when its domain in the problem is infinite.';

-- ----------------------------------------------------------------------------
-- Operators: The symbols formal statements are built from: binders (quantifiers, limits), connectives, relations, arithmetic and the functions of the model (c, x, rule30, cTail, ...).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS operators (
  operator_id                         TEXT                 PRIMARY KEY          -- Name of the operator.
);
ALTER TABLE operators ADD COLUMN IF NOT EXISTS symbol TEXT;                                         -- How it is written.
ALTER TABLE operators ADD COLUMN IF NOT EXISTS kind TEXT;                                           -- binder, infix, prefix, apply, atom, var or const: how a term with this operator is written out.
ALTER TABLE operators ADD COLUMN IF NOT EXISTS arity INTEGER;                                       -- Number of arguments (a binder has two: its condition and its body).
ALTER TABLE operators ADD COLUMN IF NOT EXISTS is_modeled INTEGER;                                  -- 1 when the model computes this operator (a table or field gives it its value); 0 when it is only a named symbol so far.
COMMENT ON TABLE operators IS 'The symbols formal statements are built from: binders (quantifiers, limits), connectives, relations, arithmetic and the functions of the model (c, x, rule30, cTail, ...).';
COMMENT ON COLUMN operators.operator_id IS 'Name of the operator.';
COMMENT ON COLUMN operators.symbol IS 'How it is written.';
COMMENT ON COLUMN operators.kind IS 'binder, infix, prefix, apply, atom, var or const: how a term with this operator is written out.';
COMMENT ON COLUMN operators.arity IS 'Number of arguments (a binder has two: its condition and its body).';
COMMENT ON COLUMN operators.is_modeled IS '1 when the model computes this operator (a table or field gives it its value); 0 when it is only a named symbol so far.';

-- ----------------------------------------------------------------------------
-- Terms: One node of a formal statement: an operator with its argument terms, a variable, or a constant. A binder holds its bound variable, its condition (Arg1) and its body (Arg2). The text, the quantifier count and whether a quantifier ranges over an infinite domain are computed from the tree.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS terms (
  term_id                             TEXT                 PRIMARY KEY          -- <predicate>-<preorder index>.
);
ALTER TABLE terms ADD COLUMN IF NOT EXISTS term_operator TEXT;                                      -- The operator (var and const for leaves).
ALTER TABLE terms ADD COLUMN IF NOT EXISTS variable TEXT;                                           -- The variable of a var leaf, or the variable a binder binds.
ALTER TABLE terms ADD COLUMN IF NOT EXISTS constant INTEGER;                                        -- The value of a const leaf.
ALTER TABLE terms ADD COLUMN IF NOT EXISTS bounds_variable INTEGER;                                 -- On a binder: 1 when its condition gives the variable a finite range (as in Theorem C's t in [T, 2T + p]).
ALTER TABLE terms ADD COLUMN IF NOT EXISTS arg1 TEXT;                                               -- First argument (a binder: its condition).
ALTER TABLE terms ADD COLUMN IF NOT EXISTS arg2 TEXT;                                               -- Second argument (a binder: its body).
ALTER TABLE terms ADD COLUMN IF NOT EXISTS arg3 TEXT;                                               -- Third argument.
ALTER TABLE terms ADD COLUMN IF NOT EXISTS arg4 TEXT;                                               -- Fourth argument.
ALTER TABLE terms ADD COLUMN IF NOT EXISTS introduced_in_loop TEXT;                                 -- The model-native loop that added this term; empty for the core predicates.
ALTER TABLE terms ADD COLUMN IF NOT EXISTS predicate_key TEXT;                                      -- The predicate whose statement this node belongs to (a plain key, not a reference: Predicates already points at the root term).
COMMENT ON TABLE terms IS 'One node of a formal statement: an operator with its argument terms, a variable, or a constant. A binder holds its bound variable, its condition (Arg1) and its body (Arg2). The text, the quantifier count and whether a quantifier ranges over an infinite domain are computed from the tree.';
COMMENT ON COLUMN terms.term_id IS '<predicate>-<preorder index>.';
COMMENT ON COLUMN terms.term_operator IS 'The operator (var and const for leaves).';
COMMENT ON COLUMN terms.variable IS 'The variable of a var leaf, or the variable a binder binds.';
COMMENT ON COLUMN terms.constant IS 'The value of a const leaf.';
COMMENT ON COLUMN terms.bounds_variable IS 'On a binder: 1 when its condition gives the variable a finite range (as in Theorem C''s t in [T, 2T + p]).';
COMMENT ON COLUMN terms.arg1 IS 'First argument (a binder: its condition).';
COMMENT ON COLUMN terms.arg2 IS 'Second argument (a binder: its body).';
COMMENT ON COLUMN terms.arg3 IS 'Third argument.';
COMMENT ON COLUMN terms.arg4 IS 'Fourth argument.';
COMMENT ON COLUMN terms.introduced_in_loop IS 'The model-native loop that added this term; empty for the core predicates.';
COMMENT ON COLUMN terms.predicate_key IS 'The predicate whose statement this node belongs to (a plain key, not a reference: Predicates already points at the root term).';

-- ----------------------------------------------------------------------------
-- Predicates: The properties stated about the model: definitions, theorems, bridge obligations and the three prize problems. The formal statement is a Terms tree; its bounded instances are computed from the model; a model-native loop adds its hypotheses here as rows.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS predicates (
  predicate_id                        TEXT                 PRIMARY KEY          -- Name of the predicate.
);
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS problem TEXT;                                       -- Definition, Known result, Theorem, Bridge obligation, Hypothesis, or the prize problem it is (P1, P2, P3).
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS instance_kind TEXT;                                 -- Which reference of PredicateInstances decides an instance.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS root_term TEXT;                                     -- The formal statement.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS statement TEXT;                                     -- A gloss in words; the formal content is the term tree.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS instance_meaning TEXT;                              -- What one bounded instance asserts.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS failure_refutes INTEGER;                            -- 1 when a failing instance is a counterexample to the statement; 0 when it only means the horizon did not decide it.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS bound_slope INTEGER;                                -- For bound hypotheses: the bound is slope * |a| + intercept.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS bound_intercept INTEGER;                            -- For bound hypotheses: see BoundSlope.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS domain_min INTEGER;                                 -- For bound hypotheses: the smallest index (N, T) the statement covers.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS covers_domain INTEGER;                              -- 1 when the instance rows enumerate the whole bounded domain of the statement, so holding on all of them verifies it; 0 when they are a sample (a model horizon shorter than the statement).
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS introduced_in_loop TEXT;                            -- The model-native loop that stated this predicate; empty for the core predicates.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS is_cached INTEGER;                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS quantifier_count_cache INTEGER;                     -- Cached QuantifierCount from the last fresh compile; read by QuantifierCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS unbounded_quantifier_count_cache INTEGER;           -- Cached UnboundedQuantifierCount from the last fresh compile; read by UnboundedQuantifierCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS unmodeled_operator_count_cache INTEGER;             -- Cached UnmodeledOperatorCount from the last fresh compile; read by UnmodeledOperatorCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS is_finitely_decidable_cache INTEGER;                -- Cached IsFinitelyDecidable from the last fresh compile; read by IsFinitelyDecidable while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS is_computable_cache INTEGER;                        -- Cached IsComputable from the last fresh compile; read by IsComputable while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS row_count_cache INTEGER;                            -- Cached RowCount from the last fresh compile; read by RowCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS instance_count_cache INTEGER;                       -- Cached InstanceCount from the last fresh compile; read by InstanceCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS holding_count_cache INTEGER;                        -- Cached HoldingCount from the last fresh compile; read by HoldingCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS failing_count_cache INTEGER;                        -- Cached FailingCount from the last fresh compile; read by FailingCount while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS is_refuted_cache INTEGER;                           -- Cached IsRefuted from the last fresh compile; read by IsRefuted while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS is_verified_cache INTEGER;                          -- Cached IsVerified from the last fresh compile; read by IsVerified while IsCached = 1.
ALTER TABLE predicates ADD COLUMN IF NOT EXISTS finite_verdict_cache TEXT;                          -- Cached FiniteVerdict from the last fresh compile; read by FiniteVerdict while IsCached = 1.
COMMENT ON TABLE predicates IS 'The properties stated about the model: definitions, theorems, bridge obligations and the three prize problems. The formal statement is a Terms tree; its bounded instances are computed from the model; a model-native loop adds its hypotheses here as rows.';
COMMENT ON COLUMN predicates.predicate_id IS 'Name of the predicate.';
COMMENT ON COLUMN predicates.problem IS 'Definition, Known result, Theorem, Bridge obligation, Hypothesis, or the prize problem it is (P1, P2, P3).';
COMMENT ON COLUMN predicates.instance_kind IS 'Which reference of PredicateInstances decides an instance.';
