-- calc_prerequisites_premise_usable
-- Field: Prerequisites.PremiseUsable
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: IsUsable from related Assertions


CREATE OR REPLACE FUNCTION calc_prerequisites_premise_usable(p_prerequisite_id TEXT)
RETURNS INTEGER AS $$
  SELECT calc_assertions_is_usable((SELECT premise FROM prerequisites WHERE prerequisite_id = p_prerequisite_id));
$$ LANGUAGE sql STABLE;

-- calc_prerequisites_premise_proof_eligible
-- Field: Prerequisites.PremiseProofEligible
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: IsProofEligible from related Assertions


CREATE OR REPLACE FUNCTION calc_prerequisites_premise_proof_eligible(p_prerequisite_id TEXT)
