-- calc_prerequisites_name
-- Field: Prerequisites.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_prerequisites_name(p_prerequisite_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(prerequisite_id, '') FROM prerequisites WHERE prerequisite_id = p_prerequisite_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_prerequisites_blocked
-- Field: Prerequisites.Blocked
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_prerequisites_blocked(p_prerequisite_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_prerequisites_premise_usable(p_prerequisite_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_prerequisites_proof_blocked
-- Field: Prerequisites.ProofBlocked
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_prerequisites_proof_blocked(p_prerequisite_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_prerequisites_premise_proof_eligible(p_prerequisite_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_prerequisites_is_self
-- Field: Prerequisites.IsSelf
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_prerequisites_is_self(p_prerequisite_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(conclusion_key, '') FROM prerequisites WHERE prerequisite_id = p_prerequisite_id), '') = COALESCE((SELECT NULLIF(premise, '') FROM prerequisites WHERE prerequisite_id = p_prerequisite_id), '') THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_prerequisites_is_blocking_ancestor
-- Field: Prerequisites.IsBlockingAncestor
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_prerequisites_is_blocking_ancestor(p_prerequisite_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((calc_prerequisites_blocked(p_prerequisite_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_prerequisites_is_self(p_prerequisite_id))::NUMERIC, 0) = 0, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

