-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rules_name(p_rule_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(rule_id, '') FROM rules WHERE rule_id = p_rule_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_rules_table_number
-- Field: Rules.TableNumber
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rules_table_number(p_rule_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((calc_rule_table_entries_weight(rule_table_entry_id))::numeric), 0) FROM rule_table_entries WHERE rule = p_rule_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_rules_black_output_count
-- Field: Rules.BlackOutputCount
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rules_black_output_count(p_rule_id TEXT)
RETURNS INTEGER AS $$
