$$ LANGUAGE sql STABLE;

-- calc_rules_is_balanced
-- Field: Rules.IsBalanced
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rules_is_balanced(p_rule_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((calc_rules_black_output_count(p_rule_id))::NUMERIC, 0) = 4 THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_rules_zero_neighborhood_output
-- Field: Rules.ZeroNeighborhoodOutput
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rules_zero_neighborhood_output(p_rule_id TEXT)
