-- calc_rule_table_entries_output_value
-- Field: RuleTableEntries.OutputValue
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rule_table_entries_output_value(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_rule_number(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, (calc_rule_table_entries_neighborhood_index(p_rule_table_entry_id))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::integer;
$$ LANGUAGE sql STABLE;

-- calc_rule_table_entries_weight
-- Field: RuleTableEntries.Weight
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rule_table_entries_weight(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
