-- calc_rule_table_entries_complement_weight
-- Field: RuleTableEntries.ComplementWeight
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rule_table_entries_complement_weight(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_output_value(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, (calc_rule_table_entries_complement_index(p_rule_table_entry_id))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_rule_table_entries_matches_polynomial
-- Field: RuleTableEntries.MatchesPolynomial
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rule_table_entries_matches_polynomial(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM rule_table_entries WHERE rule_table_entry_id = p_rule_table_entry_id))::NUMERIC, 0) = 1 THEN ((SELECT matches_polynomial_cache FROM rule_table_entries WHERE rule_table_entry_id = p_rule_table_entry_id))::text ELSE (CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_output_value(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_polynomial_value(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 0 THEN (1)::text ELSE (0)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_rule_table_entries_is_left_sensitive
-- Field: RuleTableEntries.IsLeftSensitive
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rule_table_entries_is_left_sensitive(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_output_value(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_left_partner_output(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_rule_table_entries_is_right_sensitive
-- Field: RuleTableEntries.IsRightSensitive
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_rule_table_entries_is_right_sensitive(p_rule_table_entry_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_output_value(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_rule_table_entries_right_partner_output(p_rule_table_entry_id)) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::integer;
