-- Field: InitialConditions.IsSingleSeed
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_initial_conditions_is_single_seed(p_initial_condition_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((calc_initial_conditions_background_value(p_initial_condition_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_initial_conditions_seed_cell_count(p_initial_condition_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_initial_conditions_black_seed_count(p_initial_condition_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_initial_conditions_origin_seed_count(p_initial_condition_id))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

