-- calc_runs_is_light_cone_exact
-- Field: Runs.IsLightConeExact
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_runs_is_light_cone_exact(p_run_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM runs WHERE run_id = p_run_id))::NUMERIC, 0) = 1 THEN ((SELECT is_light_cone_exact_cache FROM runs WHERE run_id = p_run_id))::text ELSE (CASE WHEN (COALESCE(COALESCE((calc_runs_is_quiescent(p_run_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_runs_background_value(p_run_id))::NUMERIC, 0) = 0, FALSE) AND COALESCE(COALESCE((calc_runs_is_single_seed(p_run_id))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_runs_is_prize_setup
