  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM runs WHERE run_id = p_run_id))::NUMERIC, 0) = 1 THEN ((SELECT is_prize_setup_cache FROM runs WHERE run_id = p_run_id))::text ELSE (CASE WHEN (COALESCE(COALESCE((calc_runs_is_single_seed(p_run_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_runs_rule_number(p_run_id))::NUMERIC, 0) = 30, FALSE)) THEN (1)::text ELSE (0)::text END)::text END)::integer;
