-- calc_time_steps_name
-- Field: TimeSteps.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_time_steps_name(p_time_step_id TEXT)
RETURNS TEXT AS $$
