-- calc_time_steps_line_density
-- Field: TimeSteps.LineDensity
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_time_steps_line_density(p_time_step_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_time_steps_black_count(p_time_step_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_time_steps_cell_count(p_time_step_id)) AS v OFFSET 0) __safe_numeric), 0), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_time_steps_center_value
-- Field: TimeSteps.CenterValue
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_time_steps_center_value(p_time_step_id TEXT)
