-- calc_time_steps_cell_updates
-- Field: TimeSteps.CellUpdates
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_time_steps_cell_updates(p_time_step_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT time FROM time_steps WHERE time_step_id = p_time_step_id))::NUMERIC, 0) = 0 THEN (0)::text ELSE (calc_time_steps_width(p_time_step_id))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_time_steps_cumulative_cell_updates
-- Field: TimeSteps.CumulativeCellUpdates
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_time_steps_cumulative_cell_updates(p_time_step_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT time FROM time_steps WHERE time_step_id = p_time_step_id))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_time_steps_previous_cumulative_cell_updates(p_time_step_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_time_steps_cell_updates(p_time_step_id)) AS v OFFSET 0) __safe_numeric), 0)))::text END)::integer;
$$ LANGUAGE sql STABLE;

