-- calc_columns_density
-- Field: Columns.Density
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_columns_density(p_column_id TEXT)
RETURNS NUMERIC AS $$
