-- calc_cells_neighborhood
-- Field: Cells.Neighborhood
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_neighborhood(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((calc_cells_left_value(p_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((calc_cells_center_value(p_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((calc_cells_right_value(p_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_transition_key
-- Field: Cells.TransitionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_cells_transition_key(p_cell_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE(((SELECT time FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 0 THEN ('')::text ELSE (CONCAT(calc_cells_run_rule(p_cell_id), '-n', CASE WHEN COALESCE((calc_cells_left_value(p_cell_id))::NUMERIC, 0) = 1 THEN ('1')::text ELSE ('0')::text END, CASE WHEN COALESCE((calc_cells_center_value(p_cell_id))::NUMERIC, 0) = 1 THEN ('1')::text ELSE ('0')::text END, CASE WHEN COALESCE((calc_cells_right_value(p_cell_id))::NUMERIC, 0) = 1 THEN ('1')::text ELSE ('0')::text END))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_cells_value
-- Field: Cells.Value
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_value(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT time FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 0 THEN (CASE WHEN COALESCE((calc_cells_seed_value(p_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (calc_cells_background_value(p_cell_id))::text END)::text ELSE (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_rule_number(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, (calc_cells_neighborhood(p_cell_id))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_state_key
-- Field: Cells.StateKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_cells_state_key(p_cell_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((calc_cells_value(p_cell_id))::NUMERIC, 0) = 1 THEN ('black')::text ELSE ('white')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_cells_is_center
-- Field: Cells.IsCenter
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_is_center(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 1 THEN ((SELECT is_center_cache FROM cells WHERE cell_id = p_cell_id))::text ELSE (CASE WHEN COALESCE(((SELECT position FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 0 THEN (1)::text ELSE (0)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_is_column_start
-- Field: Cells.IsColumnStart
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_is_column_start(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT time FROM cells WHERE cell_id = p_cell_id) = ABS((SELECT position FROM cells WHERE cell_id = p_cell_id))), (((SELECT time FROM cells WHERE cell_id = p_cell_id)) IS NULL AND (ABS((SELECT position FROM cells WHERE cell_id = p_cell_id))) IS NULL)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_right_offset
-- Field: Cells.RightOffset
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_right_offset(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM cells WHERE cell_id = p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT position FROM cells WHERE cell_id = p_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_left_offset
-- Field: Cells.LeftOffset
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_left_offset(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM cells WHERE cell_id = p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT position FROM cells WHERE cell_id = p_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_column_ones
-- Field: Cells.ColumnOnes
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_column_ones(p_cell_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_cells_value(p_cell_id) AS val) SELECT (CASE WHEN COALESCE((calc_cells_is_column_start(p_cell_id))::NUMERIC, 0) = 1 THEN ((SELECT val FROM __erb_dedup_v1))::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_prior_column_ones(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0)))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_prefix_length
-- Field: Cells.PrefixLength
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_prefix_length(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 1 THEN ((SELECT prefix_length_cache FROM cells WHERE cell_id = p_cell_id))::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM cells WHERE cell_id = p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_column_density
-- Field: Cells.ColumnDensity
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_cells_column_density(p_cell_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_column_ones(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_prefix_length(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_cells_discrepancy
-- Field: Cells.Discrepancy
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_discrepancy(p_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((SELECT is_cached FROM cells WHERE cell_id = p_cell_id))::NUMERIC, 0) = 1 THEN ((SELECT discrepancy_cache FROM cells WHERE cell_id = p_cell_id))::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_column_ones(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_cells_prefix_length(p_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_cells_abs_discrepancy
-- Field: Cells.AbsDiscrepancy
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_cells_abs_discrepancy(p_cell_id TEXT)
RETURNS INTEGER AS $$
