-- calc_mismatch_windows_window_end
-- Field: MismatchWindows.WindowEnd
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_mismatch_windows_window_end(p_mismatch_window_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT onset FROM mismatch_windows WHERE mismatch_window_id = p_mismatch_window_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_mismatch_windows_period_length(p_mismatch_window_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_mismatch_windows_center_in_window
