CREATE OR REPLACE FUNCTION calc_mismatch_windows_center_in_window(p_mismatch_window_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_mismatch_windows_center_witness(p_mismatch_window_id), 0) <= COALESCE(calc_mismatch_windows_window_end(p_mismatch_window_id), 0) THEN (1)::text ELSE (0)::text END)::integer;
