-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_mismatch_windows_window_holds(p_mismatch_window_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_mismatch_windows_center_in_window(p_mismatch_window_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_mismatch_windows_neighbor_in_window(p_mismatch_window_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) > 0 THEN (1)::text ELSE (0)::text END)::integer;
