-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_periodic_words_is_nonconstant(p_periodic_word_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_periodic_words_ones_count(p_periodic_word_id) AS val) SELECT (CASE WHEN (COALESCE(COALESCE(((SELECT val FROM __erb_dedup_v1))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT val FROM __erb_dedup_v1), 0) < COALESCE((SELECT length FROM periodic_words WHERE periodic_word_id = p_periodic_word_id), 0), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

