CREATE OR REPLACE FUNCTION calc_periodic_words_is_in_b9_domain(p_periodic_word_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((calc_periodic_words_is_nonconstant(p_periodic_word_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((calc_periodic_words_is_primitive(p_periodic_word_id))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
