-- calc_tail_cells_neighborhood
-- Field: TailCells.Neighborhood
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tail_cells_neighborhood(p_tail_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((calc_tail_cells_left_value(p_tail_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE((calc_tail_cells_center_value(p_tail_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT position FROM tail_cells WHERE tail_cell_id = p_tail_cell_id))::NUMERIC, 0) = -1 THEN (CASE WHEN COALESCE((calc_tail_cells_center_term_value(p_tail_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE((calc_tail_cells_right_value(p_tail_cell_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_tail_cells_value
-- Field: TailCells.Value
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tail_cells_value(p_tail_cell_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM tail_cells WHERE tail_cell_id = p_tail_cell_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tail_cells_onset(p_tail_cell_id)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (calc_tail_cells_real_value(p_tail_cell_id))::text ELSE (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tail_cells_rule_number(p_tail_cell_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, (calc_tail_cells_neighborhood(p_tail_cell_id))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END)::integer;
$$ LANGUAGE sql STABLE;

