-- Field: TailChecks.LeftBit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tail_checks_left_bit(p_tail_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT time FROM tail_checks WHERE tail_check_id = p_tail_check_id), 0) < COALESCE(calc_tail_checks_onset(p_tail_check_id), 0) THEN (CASE WHEN COALESCE((calc_tail_checks_real_left_value(p_tail_check_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE((calc_tail_checks_tail_left_value(p_tail_check_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_tail_checks_is_one_time
