CREATE OR REPLACE FUNCTION calc_tail_checks_is_one_time(p_tail_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((calc_tail_checks_term_value(p_tail_check_id))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::integer;
