-- calc_tail_checks_is_violation
-- Field: TailChecks.IsViolation
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tail_checks_is_violation(p_tail_check_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((calc_tail_checks_is_one_time(p_tail_check_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tail_checks_next_value(p_tail_check_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_tail_checks_left_bit(p_tail_check_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE(1, 0))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_tail_checks_first_violation_from
-- Field: TailChecks.FirstViolationFrom
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_tail_checks_first_violation_from(p_tail_check_id TEXT)
RETURNS INTEGER AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_tail_checks_horizon(p_tail_check_id) AS val) SELECT (CASE WHEN COALESCE((calc_tail_checks_is_violation(p_tail_check_id))::NUMERIC, 0) = 1 THEN ((SELECT time FROM tail_checks WHERE tail_check_id = p_tail_check_id))::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT time FROM tail_checks WHERE tail_check_id = p_tail_check_id)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE (calc_tail_checks_next_first_violation(p_tail_check_id))::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

