$$ LANGUAGE sql STABLE;

-- calc_computations_is_correct
-- Field: Computations.IsCorrect
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_computations_is_correct(p_computation_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_computations_output_value(p_computation_id), 0) = COALESCE(calc_computations_center_value(p_computation_id), 0) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_computations_effort
-- Field: Computations.Effort
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_computations_effort(p_computation_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_computations_effort_rule(p_computation_id), '') = 'cone-updates' THEN (calc_computations_cone_updates(p_computation_id))::text ELSE (1)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_computations_effort_ratio
-- Field: Computations.EffortRatio
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_computations_effort_ratio(p_computation_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_computations_effort(p_computation_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_computations_target_index(p_computation_id)) AS v OFFSET 0) __safe_numeric), 0), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_computations_is_horizon
-- Field: Computations.IsHorizon
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_computations_is_horizon(p_computation_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_computations_target_index(p_computation_id), 0) = COALESCE(calc_computations_depth(p_computation_id), 0) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_computations_is_half_horizon
-- Field: Computations.IsHalfHorizon
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_computations_is_half_horizon(p_computation_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE(calc_computations_target_index(p_computation_id), 0) = COALESCE(FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_computations_depth(p_computation_id)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE(2, 0), 0)))::NUMERIC)::BIGINT, 0) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

