-- calc_terms_rendered
-- Field: Terms.Rendered
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_terms_rendered(p_term_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_terms_op_kind(p_term_id) AS val), __erb_dedup_v2 AS (SELECT calc_terms_var_symbol(p_term_id) AS val), __erb_dedup_v3 AS (SELECT calc_terms_op_symbol(p_term_id) AS val), __erb_dedup_v4 AS (SELECT calc_terms_arg1_text(p_term_id) AS val), __erb_dedup_v5 AS (SELECT calc_terms_arg2_text(p_term_id) AS val), __erb_dedup_v6 AS (SELECT calc_terms_op_arity(p_term_id) AS val) SELECT (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'var' THEN ((SELECT val FROM __erb_dedup_v2))::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'const' THEN (CONCAT('', (SELECT constant FROM terms WHERE term_id = p_term_id)))::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'atom' THEN ((SELECT val FROM __erb_dedup_v3))::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'binder' THEN (CONCAT((SELECT val FROM __erb_dedup_v3), '[', (SELECT val FROM __erb_dedup_v2), ', ', (SELECT val FROM __erb_dedup_v4), ', ', (SELECT val FROM __erb_dedup_v5), ']'))::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'infix' THEN (CONCAT('(', (SELECT val FROM __erb_dedup_v4), ' ', (SELECT val FROM __erb_dedup_v3), ' ', (SELECT val FROM __erb_dedup_v5), ')'))::text ELSE (CASE WHEN COALESCE((SELECT val FROM __erb_dedup_v1), '') = 'prefix' THEN (CONCAT((SELECT val FROM __erb_dedup_v3), (SELECT val FROM __erb_dedup_v4)))::text ELSE (CONCAT((SELECT val FROM __erb_dedup_v3), '[', (SELECT val FROM __erb_dedup_v4), CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v6))::NUMERIC, 0) >= 2 THEN (CONCAT(', ', (SELECT val FROM __erb_dedup_v5)))::text ELSE ('')::text END, CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v6))::NUMERIC, 0) >= 3 THEN (CONCAT(', ', calc_terms_arg3_text(p_term_id)))::text ELSE ('')::text END, CASE WHEN COALESCE(((SELECT val FROM __erb_dedup_v6))::NUMERIC, 0) >= 4 THEN (CONCAT(', ', calc_terms_arg4_text(p_term_id)))::text ELSE ('')::text END, ']'))::text END)::text END)::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

