 COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.center_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.right_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_runs_background_value(run_id)::integer FROM runs WHERE run_id = (SELECT NULLIF(t.run::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((SELECT (NULLIF(t.time::text,''))::integer))::text END)::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT (NULLIF(t.time::text,''))::integer))::NUMERIC, 0) = 0 THEN (CASE WHEN COALESCE(((SELECT calc_seed_cells_state_value(seed_cell_id)::integer FROM seed_cells WHERE seed_cell_id = (SELECT NULLIF(t.seed_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE ((SELECT calc_runs_background_value(run_id)::integer FROM runs WHERE run_id = (SELECT NULLIF(t.run::text,''))))::text END)::text ELSE (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_runs_rule_number(run_id)::integer FROM runs WHERE run_id = (SELECT NULLIF(t.run::text,'')))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.left_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.center_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.right_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.center_parent,''), 'value'))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.center_parent,''), 'run_start')))::text ELSE ((SELECT (NULLIF(t.time::text,''))::integer))::text END)::text END)::text END
    ))
    FROM cells t
    WHERE NOT (a.settled ? t.cell_id) AND NOT (NULLIF(t.left_parent,'') IS NULL AND NULLIF(t.center_parent,'') IS NULL AND NULLIF(t.right_parent,'') IS NULL) AND (NULLIF(t.left_parent,'') IS NULL OR a.settled ? t.left_parent) AND (NULLIF(t.center_parent,'') IS NULL OR a.settled ? t.center_parent) AND (NULLIF(t.right_parent,'') IS NULL OR a.settled ? t.right_parent)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM cells t
    WHERE NOT (a.settled ? t.cell_id) AND NOT (NULLIF(t.left_parent,'') IS NULL AND NULLIF(t.center_parent,'') IS NULL AND NULLIF(t.right_parent,'') IS NULL) AND (NULLIF(t.left_parent,'') IS NULL OR a.settled ? t.left_parent) AND (NULLIF(t.center_parent,'') IS NULL OR a.settled ? t.center_parent) AND (NULLIF(t.right_parent,'') IS NULL OR a.settled ? t.right_parent))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.cell_id,                                                                    -- <run>-t<time>p<position>.
  calc_cells_name(t.cell_id) AS name,                                           -- Display alias.
  t.run,                                                                        -- The run.
  t.time_step,                                                                  -- The line (time step) this cell is on.
  t."column",                                                                   -- The column (position) this cell is in.
  t.seed_cell,                                                                  -- At t = 0: the seed cell listed at this position, if any.
  t.time,                                                                       -- Time step t.
  t.position,                                                                   -- Position i.
  t.left_parent,                                                                -- Cell (t-1, i-1); empty outside the cone.
  t.center_parent,                                                              -- Cell (t-1, i): the previous term of this column; empty outside the cone.
  t.right_parent,                                                               -- Cell (t-1, i+1); empty outside the cone.
  calc_cells_rule_number(t.cell_id) AS rule_number,                             -- The rule number of the run.
  calc_cells_run_rule(t.cell_id) AS run_rule,                                   -- The rule of the run.
  calc_cells_background_value(t.cell_id) AS background_value,                   -- The background state of the run.
  calc_cells_seed_value(t.cell_id) AS seed_value,                               -- State of the seed cell here, if listed.
  (SELECT settled #>> ARRAY[NULLIF(t.left_parent,''), 'value'] FROM settled)::integer AS left_value,-- Value of the left parent (blank outside the cone).
  (SELECT settled #>> ARRAY[NULLIF(t.center_parent,''), 'value'] FROM settled)::integer AS center_value,-- Value of the center parent: the previous term of this column.
  (SELECT settled #>> ARRAY[NULLIF(t.right_parent,''), 'value'] FROM settled)::integer AS right_value,-- Value of the right parent.
  (((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text((SELECT s2.settled FROM settled s2), NULLIF(t.left_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text((SELECT s2.settled FROM settled s2), NULLIF(t.center_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text((SELECT s2.settled FROM settled s2), NULLIF(t.right_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))))::integer AS neighborhood,-- Index of the parents' neighborhood; a blank parent is white (exact when the run is light-cone exact).
  calc_cells_transition_key(t.cell_id) AS transition_key,                       -- The RuleTableEntry that produced this cell; blank at t = 0.
  (SELECT settled #>> ARRAY[t.cell_id::text, 'value'] FROM settled)::integer AS value,-- The cell: the initial condition at t = 0, otherwise bit Neighborhood of the rule number.
  calc_cells_state_key(t.cell_id) AS state_key,                                 -- The color of the cell.
  calc_cells_is_center(t.cell_id) AS is_center,                                 -- 1 on the center column c(t) = x(0, t).
  calc_cells_is_column_start(t.cell_id) AS is_column_start,                     -- 1 on the first computed cell of its column; earlier terms are background.
  calc_cells_right_offset(t.cell_id) AS right_offset,                           -- k of the right-edge diagonal y_k(t) = x(t-k, t) this cell lies on.
  calc_cells_left_offset(t.cell_id) AS left_offset,                             -- k of the left-edge diagonal w_k(t) = x(-t+k, t) this cell lies on.
  (SELECT settled #>> ARRAY[NULLIF(t.center_parent,''), 'column_ones'] FROM settled)::integer AS prior_column_ones,-- Black terms of this column through t - 1.
  (SELECT settled #>> ARRAY[t.cell_id::text, 'column_ones'] FROM settled)::integer AS column_ones,-- Black terms of this column in the prefix 0 .. t (background terms are white).
  calc_cells_prefix_length(t.cell_id) AS prefix_length,                         -- Terms in the prefix 0 .. t.
  calc_cells_column_density(t.cell_id) AS column_density,                       -- Share of black in the prefix: the running average of Problem 2.
  calc_cells_discrepancy(t.cell_id) AS discrepancy,                             -- Ones minus zeros in the prefix.
  calc_cells_abs_discrepancy(t.cell_id) AS abs_discrepancy,                     -- |ones - zeros| in the prefix.
  calc_cells_density_deviation(t.cell_id) AS density_deviation,                 -- Distance of the running density from 1/2.
  (SELECT settled #>> ARRAY[NULLIF(t.center_parent,''), 'run_start'] FROM settled)::integer AS prior_run_start,-- Start of the constant run the previous term belongs to.
  (SELECT settled #>> ARRAY[t.cell_id::text, 'run_start'] FROM settled)::integer AS run_start,-- First time step of the constant run this term belongs to. (Equality is written as a difference: rulebook-to-postgres mistypes field = field inside a self-referencing chain, docs/toolchain-gaps.md gap 7.)
  calc_cells_run_length(t.cell_id) AS run_length,                               -- Length of the constant run so far.
  calc_cells_run_bound(t.cell_id) AS run_bound,                                 -- Theorem D, the center-run bounds: a black run starting at T ends by 2T+1, a white one by 4T+5.
  calc_cells_violates_run_bound(t.cell_id) AS violates_run_bound,               -- 1 when this center term lies past the Theorem D bound of its run.
  calc_cells_run_bound_holds(t.cell_id) AS run_bound_holds,                     -- Theorem D instance: 1 when this term respects the bound.
  calc_cells_claim_count(t.cell_id) AS claim_count,                             -- Accelerator claims made about this cell.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.is_center_cache,                                                            -- Cached IsCenter from the last fresh compile; read by IsCenter while IsCached = 1.
  t.prefix_length_cache,                                                        -- Cached PrefixLength from the last fresh compile; read by PrefixLength while IsCached = 1.
  t.discrepancy_cache,                                                          -- Cached Discrepancy from the last fresh compile; read by Discrepancy while IsCached = 1.
  t.run_start_cache,                                                            -- Cached RunStart from the last fresh compile; read by RunStart while IsCached = 1.
  t.run_length_cache,                                                           -- Cached RunLength from the last fresh compile; read by RunLength while IsCached = 1.
  t.run_bound_holds_cache                                                       -- Cached RunBoundHolds from the last fresh compile; read by RunBoundHolds while IsCached = 1.
FROM cells t;

-- ----------------------------------------------------------------------------
-- vw_periods: Candidate periods p >= 1 for Problem 1 (bounded at 24 in the model; unbounded in the problem).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_periods CASCADE;
CREATE VIEW vw_periods WITH (security_invoker = ON) AS
SELECT
  t.period_id,                                                                  -- p<length>.
  calc_periods_name(t.period_id) AS name,                                       -- Display alias.
  t.length,                                                                     -- The period p.
  calc_periods_test_count(t.period_id) AS test_count                            -- Columns tested against this period.
FROM periods t;

-- ----------------------------------------------------------------------------
-- vw_period_tests: Is this column eventually periodic with this period? A summary of its PeriodicityCandidates: every onset up to the last mismatch is refuted; later onsets survive only because the horizon ends.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_period_tests CASCADE;
CREATE VIEW vw_period_tests WITH (security_invoker = ON) AS
SELECT
  t.period_test_id,                                                             -- <column>-p<period>.
  calc_period_tests_name(t.period_test_id) AS name,                             -- Display alias.
  t."column",                                                                   -- The column tested.
  t.period,                                                                     -- The period p.
  calc_period_tests_period_length(t.period_test_id) AS period_length,           -- p.
  calc_period_tests_depth(t.period_test_id) AS depth,                           -- The horizon.
  calc_period_tests_position(t.period_test_id) AS position,                     -- The column position.
  calc_period_tests_last_onset(t.period_test_id) AS last_onset,                 -- The last onset T whose comparison c(T) vs c(T + p) is inside the horizon.
  calc_period_tests_comparison_count(t.period_test_id) AS comparison_count,     -- Comparisons x(i, t) vs x(i, t + p) inside the horizon.
  calc_period_tests_mismatch_count(t.period_test_id) AS mismatch_count,         -- Comparisons that differ.
  calc_period_tests_last_mismatch_time(t.period_test_id) AS last_mismatch_time, -- The last t with x(i, t + p) != x(i, t). Every onset T <= it is refuted.
  calc_period_tests_longest_agreement_streak(t.period_test_id) AS longest_agreement_streak,-- Longest stretch on which the column looked p-periodic.
  calc_period_tests_refuted_candidate_count(t.period_test_id) AS refuted_candidate_count,-- Onsets with a witness inside the horizon.
  calc_period_tests_first_surviving_onset(t.period_test_id) AS first_surviving_onset,-- The first onset the horizon cannot refute.
  calc_period_tests_final_agreement_length(t.period_test_id) AS final_agreement_length,-- Matching comparisons after the last mismatch, up to the horizon.
  calc_period_tests_onset_bound(t.period_test_id) AS onset_bound,               -- Bounded form of Problem 1: every onset up to this must be refuted.
  calc_period_tests_bounded_refutation_holds(t.period_test_id) AS bounded_refutation_holds,-- 1 when every onset T <= OnsetBound has a mismatch at some t >= T.
  calc_period_tests_window_count(t.period_test_id) AS window_count,             -- Theorem C windows for this period that end inside the horizon.
  calc_period_tests_window_failure_count(t.period_test_id) AS window_failure_count,-- Windows with no mismatch in either column. Theorem C says 0.
  calc_period_tests_center_witness_window_count(t.period_test_id) AS center_witness_window_count,-- Windows where column 0 alone has the mismatch.
  calc_period_tests_windows_hold(t.period_test_id) AS windows_hold,             -- 1 when every Theorem C window of this period holds.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.last_mismatch_time_cache,                                                   -- Cached LastMismatchTime from the last fresh compile; read by LastMismatchTime while IsCached = 1.
  t.longest_agreement_streak_cache,                                             -- Cached LongestAgreementStreak from the last fresh compile; read by LongestAgreementStreak while IsCached = 1.
  t.bounded_refutation_holds_cache,                                             -- Cached BoundedRefutationHolds from the last fresh compile; read by BoundedRefutationHolds while IsCached = 1.
  t.window_count_cache,                                                         -- Cached WindowCount from the last fresh compile; read by WindowCount while IsCached = 1.
  t.window_failure_count_cache,                                                 -- Cached WindowFailureCount from the last fresh compile; read by WindowFailureCount while IsCached = 1.
  t.windows_hold_cache                                                          -- Cached WindowsHold from the last fresh compile; read by WindowsHold while IsCached = 1.
FROM period_tests t;

-- ----------------------------------------------------------------------------
-- vw_periodicity_candidates: The hypothesis 'column i is periodic with period p from onset T' (Problem 1 quantifies over these (p, T)). Each row is also the comparison x(i, T) vs x(i, T + p); the chain to T + 1 finds the first mismatch at or after T: the witness that refutes the candidate.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_periodicity_candidates: The hypothesis 'column i is periodic with period p from onset T' (Problem 1 quantifies over these (p, T)). Each row is also the comparison x(i, T) vs x(i, T + p); the chain to T + 1 finds the first mismatch at or after T: the witness that refutes the candidate.
-- SELF-REFERENTIAL SETTLE: PeriodicityCandidates has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: first_mismatch_from, agreement_run_from. Drivers: next_candidate.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_periodicity_candidates CASCADE;
CREATE VIEW vw_periodicity_candidates WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.periodicity_candidate_id, jsonb_build_object(
      'first_mismatch_from', CASE WHEN COALESCE((CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((CASE WHEN COALESCE(((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.earlier_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.later_cell::text,'')))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::NUMERIC, 0) = 1 THEN ((SELECT (NULLIF(t.onset::text,''))::integer))::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.onset::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_period_tests_last_onset(period_test_id)::integer FROM period_tests WHERE period_test_id = (SELECT NULLIF(t.period_test::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_period_tests_last_onset(period_test_id)::integer FROM period_tests WHERE period_test_id = (SELECT NULLIF(t.period_test::text,'')))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE ((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.next_candidate,''), 'first_mismatch_from')))::text END)::text END,
      'agreement_run_from', CASE WHEN COALESCE((CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((CASE WHEN COALESCE(((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.earlier_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.later_cell::text,'')))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::NUMERIC, 0) = 1 THEN (0)::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.onset::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_period_tests_last_onset(period_test_id)::integer FROM period_tests WHERE period_test_id = (SELECT NULLIF(t.period_test::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (1)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.next_candidate,''), 'agreement_run_from'))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END)::text END
    ))
    FROM periodicity_candidates t WHERE NULLIF(t.next_candidate,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.periodicity_candidate_id, jsonb_build_object(
      'first_mismatch_from', CASE WHEN COALESCE((CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((CASE WHEN COALESCE(((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.earlier_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.later_cell::text,'')))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::NUMERIC, 0) = 1 THEN ((SELECT (NULLIF(t.onset::text,''))::integer))::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.onset::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_period_tests_last_onset(period_test_id)::integer FROM period_tests WHERE period_test_id = (SELECT NULLIF(t.period_test::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_period_tests_last_onset(period_test_id)::integer FROM period_tests WHERE period_test_id = (SELECT NULLIF(t.period_test::text,'')))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.next_candidate,''), 'first_mismatch_from')))::text END)::text END,
      'agreement_run_from', CASE WHEN COALESCE((CASE WHEN COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((CASE WHEN COALESCE(((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.earlier_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.later_cell::text,'')))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::NUMERIC, 0) = 1 THEN (0)::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.onset::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_period_tests_last_onset(period_test_id)::integer FROM period_tests WHERE period_test_id = (SELECT NULLIF(t.period_test::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN (1)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.next_candidate,''), 'agreement_run_from'))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text END)::text END
    ))
    FROM periodicity_candidates t
    WHERE NOT (a.settled ? t.periodicity_candidate_id) AND NOT (NULLIF(t.next_candidate,'') IS NULL) AND (NULLIF(t.next_candidate,'') IS NULL OR a.settled ? t.next_candidate)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM periodicity_candidates t
    WHERE NOT (a.settled ? t.periodicity_candidate_id) AND NOT (NULLIF(t.next_candidate,'') IS NULL) AND (NULLIF(t.next_candidate,'') IS NULL OR a.settled ? t.next_candidate))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.periodicity_candidate_id,                                                   -- <period test>-T<onset>.
  calc_periodicity_candidates_name(t.periodicity_candidate_id) AS name,         -- Display alias.
  t.period_test,                                                                -- The column and period.
  t.onset,                                                                      -- The onset T.
  t.earlier_cell,                                                               -- x(i, T); empty before the light cone reaches the column (white).
  t.later_cell,                                                                 -- x(i, T + p).
  t.next_candidate,                                                             -- The candidate with onset T + 1; empty at the last onset.
  calc_periodicity_candidates_period_length(t.periodicity_candidate_id) AS period_length,-- p.
  calc_periodicity_candidates_last_onset(t.periodicity_candidate_id) AS last_onset,-- Last onset inside the horizon.
  calc_periodicity_candidates_onset_bound(t.periodicity_candidate_id) AS onset_bound,-- Largest onset in the bounded form of Problem 1.
  calc_periodicity_candidates_earlier_value(t.periodicity_candidate_id) AS earlier_value,-- x(i, T).
  calc_periodicity_candidates_later_value(t.periodicity_candidate_id) AS later_value,-- x(i, T + p).
  calc_periodicity_candidates_earlier_bit(t.periodicity_candidate_id) AS earlier_bit,-- x(i, T), white outside the cone.
  calc_periodicity_candidates_is_mismatch(t.periodicity_candidate_id) AS is_mismatch,-- 1 when x(i, T + p) != x(i, T).
  (SELECT settled #>> ARRAY[NULLIF(t.next_candidate,''), 'first_mismatch_from'] FROM settled)::integer AS next_first_mismatch,-- Witness of the candidate with onset T + 1.
  (SELECT settled #>> ARRAY[t.periodicity_candidate_id::text, 'first_mismatch_from'] FROM settled)::integer AS first_mismatch_from,-- The witness: the first t >= T with x(i, t + p) != x(i, t); LastOnset + 1 when there is none inside the horizon.
  calc_periodicity_candidates_is_refuted(t.periodicity_candidate_id) AS is_refuted,-- 1 when the horizon holds a witness against this candidate.
  (SELECT settled #>> ARRAY[NULLIF(t.next_candidate,''), 'agreement_run_from'] FROM settled)::integer AS next_agreement_run,-- Agreement run of onset T + 1.
  (SELECT settled #>> ARRAY[t.periodicity_candidate_id::text, 'agreement_run_from'] FROM settled)::integer AS agreement_run_from,-- Consecutive matching comparisons starting at T.
  calc_periodicity_candidates_in_bounded_domain(t.periodicity_candidate_id) AS in_bounded_domain-- 1 when the onset is in the bounded form of Problem 1 (T <= (depth - p)/2).
FROM periodicity_candidates t;

-- ----------------------------------------------------------------------------
-- vw_mismatch_windows: Theorem C for one (T, p): some i in {0, 1} and t in [T, 2T + p] have x(i, t) != x(i, t + p). Only windows that end inside the horizon are rows.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_mismatch_windows CASCADE;
CREATE VIEW vw_mismatch_windows WITH (security_invoker = ON) AS
SELECT
  t.mismatch_window_id,                                                         -- tc-p<period>-T<onset>.
  calc_mismatch_windows_name(t.mismatch_window_id) AS name,                     -- Display alias.
  t.onset,                                                                      -- T.
  t.period,                                                                     -- p.
  t.center_test,                                                                -- The center column test for p (for the roll-up).
  t.center_candidate,                                                           -- Column 0 with period p from onset T.
  t.neighbor_candidate,                                                         -- Column 1 with period p from onset T.
  calc_mismatch_windows_period_length(t.mismatch_window_id) AS period_length,   -- p.
  calc_mismatch_windows_center_witness(t.mismatch_window_id) AS center_witness, -- First mismatch at or after T in column 0.
  calc_mismatch_windows_neighbor_witness(t.mismatch_window_id) AS neighbor_witness,-- First mismatch at or after T in column 1.
  calc_mismatch_windows_window_end(t.mismatch_window_id) AS window_end,         -- 2T + p.
  calc_mismatch_windows_center_in_window(t.mismatch_window_id) AS center_in_window,-- 1 when column 0 alone has a mismatch in the window (Theorem C does not promise this).
  calc_mismatch_windows_neighbor_in_window(t.mismatch_window_id) AS neighbor_in_window,-- 1 when column 1 has a mismatch in the window.
  calc_mismatch_windows_window_holds(t.mismatch_window_id) AS window_holds      -- Theorem C instance: 1 when column 0 or column 1 has a mismatch in [T, 2T + p].
FROM mismatch_windows t;

-- ----------------------------------------------------------------------------
-- vw_left_consistency_checks: TX at one time step of the real center: when c(t) = 1 the rule at column 0 forces c(t + 1) = NOT x(-1, t), so the center is decided by its own past through the left half. After a 0 the left half says nothing.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_left_consistency_checks CASCADE;
CREATE VIEW vw_left_consistency_checks WITH (security_invoker = ON) AS
SELECT
  t.left_consistency_check_id,                                                  -- <run>-tx-t<time>.
  calc_left_consistency_checks_name(t.left_consistency_check_id) AS name,       -- Display alias.
  t.time,                                                                       -- t.
  t.term,                                                                       -- c(t).
  t.next_term,                                                                  -- c(t + 1).
  t.left_cell,                                                                  -- x(-1, t); empty at t = 0 (white).
  calc_left_consistency_checks_term_value(t.left_consistency_check_id) AS term_value,-- c(t).
  calc_left_consistency_checks_next_value(t.left_consistency_check_id) AS next_value,-- c(t + 1).
  calc_left_consistency_checks_left_value(t.left_consistency_check_id) AS left_value,-- x(-1, t).
  calc_left_consistency_checks_left_bit(t.left_consistency_check_id) AS left_bit,-- x(-1, t), white outside the cone.
  calc_left_consistency_checks_is_one_time(t.left_consistency_check_id) AS is_one_time,-- 1 when c(t) = 1, the times at which the left half decides the next term.
  calc_left_consistency_checks_forced_next(t.left_consistency_check_id) AS forced_next,-- The value NOT x(-1, t) the left half forces at a one-time.
  calc_left_consistency_checks_is_consistent(t.left_consistency_check_id) AS is_consistent,-- TX instance: 1 unless c(t) = 1 and c(t + 1) != NOT x(-1, t).
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.is_consistent_cache                                                         -- Cached IsConsistent from the last fresh compile; read by IsConsistent while IsCached = 1.
FROM left_consistency_checks t;

-- ----------------------------------------------------------------------------
-- vw_periodic_words: A finite word a; the tail a a a ... is what an eventually periodic center would repeat. Its least period, constancy and B9 membership are computed from its letters.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_periodic_words CASCADE;
CREATE VIEW vw_periodic_words WITH (security_invoker = ON) AS
SELECT
  t.periodic_word_id,                                                           -- w<letters>.
  calc_periodic_words_name(t.periodic_word_id) AS name,                         -- Display alias.
  t.length,                                                                     -- Number of letters |a|.
  calc_periodic_words_ones_count(t.periodic_word_id) AS ones_count,             -- Black letters.
  calc_periodic_words_is_nonconstant(t.periodic_word_id) AS is_nonconstant,     -- 1 when the word has both colors.
  calc_periodic_words_least_period(t.periodic_word_id) AS least_period,         -- Smallest d >= 1 with a rotated by d equal to a (d = |a| always qualifies).
  calc_periodic_words_is_primitive(t.periodic_word_id) AS is_primitive,         -- 1 when the least period is the full length.
  calc_periodic_words_is_in_b9_domain(t.periodic_word_id) AS is_in_b9_domain,   -- 1 for a nonconstant word of least period |a|: the tails B9 excludes.
  calc_periodic_words_tail_candidate_count(t.periodic_word_id) AS tail_candidate_count,-- Onsets this tail is spliced on at.
  calc_periodic_words_killed_candidate_count(t.periodic_word_id) AS killed_candidate_count,-- Of those, the ones left-consistency kills inside the horizon.
  calc_periodic_words_killed_excess_max(t.periodic_word_id) AS killed_excess_max,-- Raw MAXIFS; over an empty set it is blank in compile-rulebook and 0 in Postgres (docs/toolchain-gaps.md gap 12), so read MaxKillExcess.
  calc_periodic_words_max_kill_excess(t.periodic_word_id) AS max_kill_excess    -- Longest a killed tail survived past its onset; -2 when no candidate of this word was killed (or none exists).
FROM periodic_words t;

-- ----------------------------------------------------------------------------
-- vw_word_letters: One letter a[k] of a word.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_word_letters CASCADE;
CREATE VIEW vw_word_letters WITH (security_invoker = ON) AS
SELECT
  t.word_letter_id,                                                             -- <word>-k<index>.
  calc_word_letters_name(t.word_letter_id) AS name,                             -- Display alias.
  t.periodic_word,                                                              -- The word.
  t.letter_index,                                                               -- k, from 0.
  t.letter_bit                                                                  -- a[k].
FROM word_letters t;

-- ----------------------------------------------------------------------------
-- vw_word_shifts: A rotation of a word by d positions; a symmetry when every letter matches its rotated partner.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_word_shifts CASCADE;
CREATE VIEW vw_word_shifts WITH (security_invoker = ON) AS
SELECT
  t.word_shift_id,                                                              -- <word>-d<shift>.
  calc_word_shifts_name(t.word_shift_id) AS name,                               -- Display alias.
  t.periodic_word,                                                              -- The word.
  t.shift,                                                                      -- d, 1 .. |a|.
  calc_word_shifts_mismatch_count(t.word_shift_id) AS mismatch_count,           -- Letters with a[k] != a[(k + d) mod |a|].
  calc_word_shifts_is_symmetry(t.word_shift_id) AS is_symmetry                  -- 1 when rotating by d leaves the word unchanged.
FROM word_shifts t;

-- ----------------------------------------------------------------------------
-- vw_word_shift_checks: One letter against its rotated partner: a[k] vs a[(k + d) mod |a|].
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_word_shift_checks CASCADE;
CREATE VIEW vw_word_shift_checks WITH (security_invoker = ON) AS
SELECT
  t.word_shift_check_id,                                                        -- <shift>-k<index>.
  calc_word_shift_checks_name(t.word_shift_check_id) AS name,                   -- Display alias.
  t.word_shift,                                                                 -- The rotation.
  t.letter,                                                                     -- a[k].
  t.partner_letter,                                                             -- a[(k + d) mod |a|].
  calc_word_shift_checks_letter_bit(t.word_shift_check_id) AS letter_bit,       -- a[k].
  calc_word_shift_checks_partner_bit(t.word_shift_check_id) AS partner_bit,     -- a[(k + d) mod |a|].
  calc_word_shift_checks_is_mismatch(t.word_shift_check_id) AS is_mismatch      -- 1 when the two letters differ.
FROM word_shift_checks t;

-- ----------------------------------------------------------------------------
-- vw_tail_candidates: The real center up to onset T, then the tail a a a ... from T: the center an eventual a-periodicity from T would have. TX says the real center is left-consistent; B9 says no left-consistent sequence ends in a nonconstant periodic tail, so every candidate must fail a one-time check. The kill uses only the real prefix and the rule, never the real center after T.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tail_candidates CASCADE;
CREATE VIEW vw_tail_candidates WITH (security_invoker = ON) AS
SELECT
  t.tail_candidate_id,                                                          -- tail-<word>-T<onset>.
  calc_tail_candidates_name(t.tail_candidate_id) AS name,                       -- Display alias.
  t.run,                                                                        -- The run whose prefix is used.
  t.periodic_word,                                                              -- The tail word a.
  t.onset,                                                                      -- T: the first time step of the tail.
  t.horizon,                                                                    -- The last time step checked (onset + 12).
  calc_tail_candidates_rule_number(t.tail_candidate_id) AS rule_number,         -- The rule.
  calc_tail_candidates_word_length(t.tail_candidate_id) AS word_length,         -- |a|.
  calc_tail_candidates_is_in_b9_domain(t.tail_candidate_id) AS is_in_b9_domain, -- 1 for a nonconstant primitive tail.
  calc_tail_candidates_kill_time(t.tail_candidate_id) AS kill_time,             -- The witness: the first one-time t >= T - 1 at which c(t + 1) != NOT x(-1, t); Horizon + 1 when none.
  calc_tail_candidates_is_killed(t.tail_candidate_id) AS is_killed,             -- 1 when left-consistency kills the tail inside the horizon.
  calc_tail_candidates_kill_excess(t.tail_candidate_id) AS kill_excess,         -- How long past the onset the tail survived (-1: killed by the first tail bit).
  calc_tail_candidates_one_time_count(t.tail_candidate_id) AS one_time_count,   -- One-times checked.
  calc_tail_candidates_cell_count(t.tail_candidate_id) AS cell_count,           -- Left-half cells computed for this tail.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.kill_time_cache,                                                            -- Cached KillTime from the last fresh compile; read by KillTime while IsCached = 1.
  t.is_killed_cache,                                                            -- Cached IsKilled from the last fresh compile; read by IsKilled while IsCached = 1.
  t.kill_excess_cache                                                           -- Cached KillExcess from the last fresh compile; read by KillExcess while IsCached = 1.
FROM tail_candidates t;

-- ----------------------------------------------------------------------------
-- vw_tail_center_terms: c'(t) of a tail candidate: the real center before the onset, the tail word's letter a[(t - T) mod |a|] from it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tail_center_terms CASCADE;
CREATE VIEW vw_tail_center_terms WITH (security_invoker = ON) AS
SELECT
  t.tail_center_term_id,                                                        -- <candidate>-c<time>.
  calc_tail_center_terms_name(t.tail_center_term_id) AS name,                   -- Display alias.
  t.tail_candidate,                                                             -- The candidate.
  t.time,                                                                       -- t.
  t.real_cell,                                                                  -- Before the onset: c(t).
  t.letter,                                                                     -- From the onset: the letter a[(t - T) mod |a|].
  calc_tail_center_terms_onset(t.tail_center_term_id) AS onset,                 -- T.
  calc_tail_center_terms_real_value(t.tail_center_term_id) AS real_value,       -- c(t).
  calc_tail_center_terms_letter_value(t.tail_center_term_id) AS letter_value,   -- a[(t - T) mod |a|].
  calc_tail_center_terms_value(t.tail_center_term_id) AS value                  -- c'(t).
FROM tail_center_terms t;

-- ----------------------------------------------------------------------------
-- vw_tail_cells: x'(i, t), i <= -1, of a tail candidate: the left half driven by c'. At the onset it equals the real left half (TX: the left half depends only on the center's past); after it, Rule 30 with c' as the right boundary. Only cells that can reach x'(-1, t) by the horizon are rows.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_tail_cells: x'(i, t), i <= -1, of a tail candidate: the left half driven by c'. At the onset it equals the real left half (TX: the left half depends only on the center's past); after it, Rule 30 with c' as the right boundary. Only cells that can reach x'(-1, t) by the horizon are rows.
-- SELF-REFERENTIAL SETTLE: TailCells has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: value. Drivers: left_parent, center_parent, right_parent.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tail_cells CASCADE;
CREATE VIEW vw_tail_cells WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.tail_cell_id, jsonb_build_object(
      'value', CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.time::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT onset::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.real_cell::text,''))))::text ELSE (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_tail_candidates_rule_number(tail_candidate_id)::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.left_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.center_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT (NULLIF(t.position::text,''))::integer))::NUMERIC, 0) = -1 THEN (CASE WHEN COALESCE(((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.center_term::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.right_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END
    ))
    FROM tail_cells t WHERE NULLIF(t.left_parent,'') IS NULL AND NULLIF(t.center_parent,'') IS NULL AND NULLIF(t.right_parent,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.tail_cell_id, jsonb_build_object(
      'value', CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.time::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT onset::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.real_cell::text,''))))::text ELSE (MOD((FLOOR(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_tail_candidates_rule_number(tail_candidate_id)::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (POWER((2)::NUMERIC, ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.left_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.center_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT (NULLIF(t.position::text,''))::integer))::NUMERIC, 0) = -1 THEN (CASE WHEN COALESCE(((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.center_term::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.right_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC)) AS v OFFSET 0) __safe_numeric), 0), 0)))::NUMERIC)::BIGINT)::NUMERIC, (2)::NUMERIC))::text END
    ))
    FROM tail_cells t
    WHERE NOT (a.settled ? t.tail_cell_id) AND NOT (NULLIF(t.left_parent,'') IS NULL AND NULLIF(t.center_parent,'') IS NULL AND NULLIF(t.right_parent,'') IS NULL) AND (NULLIF(t.left_parent,'') IS NULL OR a.settled ? t.left_parent) AND (NULLIF(t.center_parent,'') IS NULL OR a.settled ? t.center_parent) AND (NULLIF(t.right_parent,'') IS NULL OR a.settled ? t.right_parent)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM tail_cells t
    WHERE NOT (a.settled ? t.tail_cell_id) AND NOT (NULLIF(t.left_parent,'') IS NULL AND NULLIF(t.center_parent,'') IS NULL AND NULLIF(t.right_parent,'') IS NULL) AND (NULLIF(t.left_parent,'') IS NULL OR a.settled ? t.left_parent) AND (NULLIF(t.center_parent,'') IS NULL OR a.settled ? t.center_parent) AND (NULLIF(t.right_parent,'') IS NULL OR a.settled ? t.right_parent))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.tail_cell_id,                                                               -- <candidate>-<time><position>.
  calc_tail_cells_name(t.tail_cell_id) AS name,                                 -- Display alias.
  t.tail_candidate,                                                             -- The candidate.
  t.time,                                                                       -- t.
  t.position,                                                                   -- i <= -1.
  t.real_cell,                                                                  -- At the onset: the real cell x(i, T).
  t.left_parent,                                                                -- x'(i - 1, t - 1); empty outside the cone (white).
  t.center_parent,                                                              -- x'(i, t - 1).
  t.right_parent,                                                               -- x'(i + 1, t - 1), for i <= -2.
  t.center_term,                                                                -- c'(t - 1), the right parent of column -1.
  calc_tail_cells_onset(t.tail_cell_id) AS onset,                               -- T.
  calc_tail_cells_rule_number(t.tail_cell_id) AS rule_number,                   -- The rule.
  calc_tail_cells_real_value(t.tail_cell_id) AS real_value,                     -- x(i, T).
  (SELECT settled #>> ARRAY[NULLIF(t.left_parent,''), 'value'] FROM settled)::integer AS left_value,-- Left parent.
  (SELECT settled #>> ARRAY[NULLIF(t.center_parent,''), 'value'] FROM settled)::integer AS center_value,-- Center parent.
  (SELECT settled #>> ARRAY[NULLIF(t.right_parent,''), 'value'] FROM settled)::integer AS right_value,-- Right parent (i <= -2).
  calc_tail_cells_center_term_value(t.tail_cell_id) AS center_term_value,       -- c'(t - 1) (i = -1).
  (((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(4, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text((SELECT s2.settled FROM settled s2), NULLIF(t.left_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text((SELECT s2.settled FROM settled s2), NULLIF(t.center_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT (NULLIF(t.position::text,''))::integer))::NUMERIC, 0) = -1 THEN (CASE WHEN COALESCE(((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.center_term::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE(((SELECT jsonb_extract_path_text((SELECT s2.settled FROM settled s2), NULLIF(t.right_parent,''), 'value')))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))))::integer AS neighborhood,-- Index of the parents' neighborhood; the right parent of column -1 is the candidate center.
  (SELECT settled #>> ARRAY[t.tail_cell_id::text, 'value'] FROM settled)::integer AS value-- x'(i, t).
FROM tail_cells t;

-- ----------------------------------------------------------------------------
-- vw_tail_checks: The one-time check at t of a tail candidate: when c'(t) = 1, left-consistency requires c'(t + 1) = NOT x'(-1, t). The chain to t + 1 finds the first violation: the kill.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_tail_checks: The one-time check at t of a tail candidate: when c'(t) = 1, left-consistency requires c'(t + 1) = NOT x'(-1, t). The chain to t + 1 finds the first violation: the kill.
-- SELF-REFERENTIAL SETTLE: TailChecks has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: first_violation_from. Drivers: next_check.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tail_checks CASCADE;
CREATE VIEW vw_tail_checks WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.tail_check_id, jsonb_build_object(
      'first_violation_from', CASE WHEN COALESCE((CASE WHEN (COALESCE(COALESCE(((CASE WHEN COALESCE(((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.term::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.next_term::text,'')))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((CASE WHEN COALESCE((SELECT (NULLIF(t.time::text,''))::integer), 0) < COALESCE((SELECT onset::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,''))), 0) THEN (CASE WHEN COALESCE(((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.real_left_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE(((SELECT calc_tail_cells_value(tail_cell_id)::integer FROM tail_cells WHERE tail_cell_id = (SELECT NULLIF(t.tail_left_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE(1, 0))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::NUMERIC, 0) = 1 THEN ((SELECT (NULLIF(t.time::text,''))::integer))::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.time::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT horizon::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT horizon::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE ((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.next_check,''), 'first_violation_from')))::text END)::text END
    ))
    FROM tail_checks t WHERE NULLIF(t.next_check,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.tail_check_id, jsonb_build_object(
      'first_violation_from', CASE WHEN COALESCE((CASE WHEN (COALESCE(COALESCE(((CASE WHEN COALESCE(((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.term::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((ABS((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT calc_tail_center_terms_value(tail_center_term_id)::integer FROM tail_center_terms WHERE tail_center_term_id = (SELECT NULLIF(t.next_term::text,'')))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((CASE WHEN COALESCE((SELECT (NULLIF(t.time::text,''))::integer), 0) < COALESCE((SELECT onset::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,''))), 0) THEN (CASE WHEN COALESCE(((SELECT calc_cells_value(cell_id)::integer FROM cells WHERE cell_id = (SELECT NULLIF(t.real_left_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text ELSE (CASE WHEN COALESCE(((SELECT calc_tail_cells_value(tail_cell_id)::integer FROM tail_cells WHERE tail_cell_id = (SELECT NULLIF(t.tail_left_cell::text,''))))::NUMERIC, 0) = 1 THEN (1)::text ELSE (0)::text END)::text END)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE(1, 0))) AS v OFFSET 0) __safe_numeric), 0))))::NUMERIC, 0) = 1, FALSE)) THEN (1)::text ELSE (0)::text END)::NUMERIC, 0) = 1 THEN ((SELECT (NULLIF(t.time::text,''))::integer))::text ELSE (CASE WHEN COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT (NULLIF(t.time::text,''))::integer)) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT horizon::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0 THEN ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT horizon::integer FROM tail_candidates WHERE tail_candidate_id = (SELECT NULLIF(t.tail_candidate::text,'')))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE(1, 0)))::text ELSE ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.next_check,''), 'first_violation_from')))::text END)::text END
    ))
    FROM tail_checks t
    WHERE NOT (a.settled ? t.tail_check_id) AND NOT (NULLIF(t.next_check,'') IS NULL) AND (NULLIF(t.next_check,'') IS NULL OR a.settled ? t.next_check)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM tail_checks t
    WHERE NOT (a.settled ? t.tail_check_id) AND NOT (NULLIF(t.next_check,'') IS NULL) AND (NULLIF(t.next_check,'') IS NULL OR a.settled ? t.next_check))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.tail_check_id,                                                              -- <candidate>-x<time>.
  calc_tail_checks_name(t.tail_check_id) AS name,                               -- Display alias.
  t.tail_candidate,                                                             -- The candidate.
  t.time,                                                                       -- t.
  t.term,                                                                       -- c'(t).
  t.next_term,                                                                  -- c'(t + 1).
  t.real_left_cell,                                                             -- Before the onset: x(-1, t) (empty at t = 0, white).
  t.tail_left_cell,                                                             -- From the onset: x'(-1, t).
  t.next_check,                                                                 -- The check at t + 1; empty at the horizon.
  calc_tail_checks_onset(t.tail_check_id) AS onset,                             -- T.
  calc_tail_checks_horizon(t.tail_check_id) AS horizon,                         -- Last time checked.
  calc_tail_checks_term_value(t.tail_check_id) AS term_value,                   -- c'(t).
  calc_tail_checks_next_value(t.tail_check_id) AS next_value,                   -- c'(t + 1).
  calc_tail_checks_real_left_value(t.tail_check_id) AS real_left_value,         -- x(-1, t).
  calc_tail_checks_tail_left_value(t.tail_check_id) AS tail_left_value,         -- x'(-1, t).
  calc_tail_checks_left_bit(t.tail_check_id) AS left_bit,                       -- x'(-1, t).
  calc_tail_checks_is_one_time(t.tail_check_id) AS is_one_time,                 -- 1 when c'(t) = 1.
  calc_tail_checks_is_violation(t.tail_check_id) AS is_violation,               -- 1 when c'(t) = 1 and c'(t + 1) != NOT x'(-1, t): the tail is not left-consistent.
  (SELECT settled #>> ARRAY[NULLIF(t.next_check,''), 'first_violation_from'] FROM settled)::integer AS next_first_violation,-- First violation from t + 1.
  (SELECT settled #>> ARRAY[t.tail_check_id::text, 'first_violation_from'] FROM settled)::integer AS first_violation_from-- First violating time >= t; Horizon + 1 when none.
FROM tail_checks t;

-- ----------------------------------------------------------------------------
-- vw_diagonals: A diagonal of the cone read as a sequence in t: right side y_k(t) = x(t - k, t), left side w_k(t) = x(k - t, t) (k = 0 is the edge). Before the cone reaches it a diagonal is white.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_diagonals: A diagonal of the cone read as a sequence in t: right side y_k(t) = x(t - k, t), left side w_k(t) = x(k - t, t) (k = 0 is the edge). Before the cone reaches it a diagonal is white.
-- SELF-REFERENTIAL SETTLE: Diagonals has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: least_period, doubles, previous_doubles, ones_per_period, previous_ones_per_period. Drivers: previous_diagonal, opposite_diagonal.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_diagonals CASCADE;
CREATE VIEW vw_diagonals WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.diagonal_id, jsonb_build_object(
      'least_period', CASE WHEN COALESCE(((SELECT COUNT(*) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1))::NUMERIC, 0) > 0 THEN (((SELECT COALESCE(MIN((period)::numeric), 0) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1)))::text ELSE (-1)::text END,
      'doubles', CASE WHEN (COALESCE(COALESCE(((SELECT (NULLIF(t."offset"::text,''))::integer))::NUMERIC, 0) >= 1, FALSE) AND COALESCE(COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT COUNT(*) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1))::NUMERIC, 0) > 0 THEN (((SELECT COALESCE(MIN((period)::numeric), 0) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1)))::text ELSE (-1)::text END) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.previous_diagonal,''), 'least_period'))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0, FALSE)) THEN (1)::text ELSE (0)::text END,
      'previous_doubles', ((SELECT calc_diagonals_doubles(diagonal_id) FROM diagonals WHERE diagonal_id = ((SELECT NULLIF(t.previous_diagonal::text,'')))::text)),
      'ones_per_period', (SELECT COALESCE(SUM((calc_diagonal_period_tests_ones_in_first_period(diagonal_period_test_id))::numeric), 0) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_least(diagonal_period_test_id) = 1),
      'previous_ones_per_period', ((SELECT calc_diagonals_ones_per_period(diagonal_id) FROM diagonals WHERE diagonal_id = ((SELECT NULLIF(t.previous_diagonal::text,'')))::text))
    ))
    FROM diagonals t WHERE NULLIF(t.previous_diagonal,'') IS NULL AND NULLIF(t.opposite_diagonal,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.diagonal_id, jsonb_build_object(
      'least_period', CASE WHEN COALESCE(((SELECT COUNT(*) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1))::NUMERIC, 0) > 0 THEN (((SELECT COALESCE(MIN((period)::numeric), 0) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1)))::text ELSE (-1)::text END,
      'doubles', CASE WHEN (COALESCE(COALESCE(((SELECT (NULLIF(t."offset"::text,''))::integer))::NUMERIC, 0) >= 1, FALSE) AND COALESCE(COALESCE(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN COALESCE(((SELECT COUNT(*) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1))::NUMERIC, 0) > 0 THEN (((SELECT COALESCE(MIN((period)::numeric), 0) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_pure_period(diagonal_period_test_id) = 1)))::text ELSE (-1)::text END) AS v OFFSET 0) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE(2, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT jsonb_extract_path_text(a.settled, NULLIF(t.previous_diagonal,''), 'least_period'))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, 0) = 0, FALSE)) THEN (1)::text ELSE (0)::text END,
      'previous_doubles', ((SELECT calc_diagonals_doubles(diagonal_id) FROM diagonals WHERE diagonal_id = ((SELECT NULLIF(t.previous_diagonal::text,'')))::text)),
      'ones_per_period', (SELECT COALESCE(SUM((calc_diagonal_period_tests_ones_in_first_period(diagonal_period_test_id))::numeric), 0) FROM diagonal_period_tests WHERE diagonal = (SELECT NULLIF(t.diagonal_id::text,'')) AND calc_diagonal_period_tests_is_least(diagonal_period_test_id) = 1),
      'previous_ones_per_period', ((SELECT calc_diagonals_ones_per_period(diagonal_id) FROM diagonals WHERE diagonal_id = ((SELECT NULLIF(t.previous_diagonal::text,'')))::text))
    ))
    FROM diagonals t
    WHERE NOT (a.settled ? t.diagonal_id) AND NOT (NULLIF(t.previous_diagonal,'') IS NULL AND NULLIF(t.opposite_diagonal,'') IS NULL) AND (NULLIF(t.previous_diagonal,'') IS NULL OR a.settled ? t.previous_diagonal) AND (NULLIF(t.opposite_diagonal,'') IS NULL OR a.settled ? t.opposite_diagonal)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM diagonals t
    WHERE NOT (a.settled ? t.diagonal_id) AND NOT (NULLIF(t.previous_diagonal,'') IS NULL AND NULLIF(t.opposite_diagonal,'') IS NULL) AND (NULLIF(t.previous_diagonal,'') IS NULL OR a.settled ? t.previous_diagonal) AND (NULLIF(t.opposite_diagonal,'') IS NULL OR a.settled ? t.opposite_diagonal))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.diagonal_id,                                                                -- <side>-k<offset>.
  calc_diagonals_name(t.diagonal_id) AS name,                                   -- Display alias.
  t.side,                                                                       -- right (y_k) or left (w_k).
  t."offset",                                                                   -- k.
  t.previous_diagonal,                                                          -- The diagonal k - 1 on the same side; empty at k = 0.
  t.opposite_diagonal,                                                          -- For a left diagonal w_k: the right diagonal y_k (one direction only).
  t.depth,                                                                      -- The horizon (the run depth).
  calc_diagonals_right_ones(t.diagonal_id) AS right_ones,                       -- Black cells with t - i = k.
  calc_diagonals_left_ones(t.diagonal_id) AS left_ones,                         -- Black cells with t + i = k.
  calc_diagonals_right_cells(t.diagonal_id) AS right_cells,                     -- Cells with t - i = k.
  calc_diagonals_left_cells(t.diagonal_id) AS left_cells,                       -- Cells with t + i = k.
  calc_diagonals_right_first_one_raw(t.diagonal_id) AS right_first_one_raw,     -- Raw MINIFS (gap 12); read FirstOneTime.
  calc_diagonals_left_first_one_raw(t.diagonal_id) AS left_first_one_raw,       -- Raw MINIFS (gap 12); read FirstOneTime.
  calc_diagonals_ones_count(t.diagonal_id) AS ones_count,                       -- Black cells on the diagonal inside the horizon.
  calc_diagonals_cell_count(t.diagonal_id) AS cell_count,                       -- Cells of the diagonal inside the cone and the horizon.
  calc_diagonals_first_one_time(t.diagonal_id) AS first_one_time,               -- First t with a black cell on the diagonal; -1 when none inside the horizon.
  calc_diagonals_pure_count(t.diagonal_id) AS pure_count,                       -- Dyadic periods the whole observed diagonal has.
  calc_diagonals_least_pure_raw(t.diagonal_id) AS least_pure_raw,               -- Raw MINIFS (gap 12); read LeastPeriod.
  (SELECT settled #>> ARRAY[t.diagonal_id::text, 'least_period'] FROM settled)::integer AS least_period,-- P_k: the least dyadic period of the diagonal from t = 0; -1 when none is certified inside the horizon.
  calc_diagonals_eventual_count(t.diagonal_id) AS eventual_count,               -- Dyadic periods the diagonal eventually has.
  calc_diagonals_least_eventual_raw(t.diagonal_id) AS least_eventual_raw,       -- Raw MINIFS (gap 12); read EventualPeriod.
  calc_diagonals_eventual_period(t.diagonal_id) AS eventual_period,             -- Least dyadic eventual period; -1 when none is certified inside the horizon.
  calc_diagonals_eventual_onset(t.diagonal_id) AS eventual_onset,               -- Onset of the least eventual period.
  (SELECT settled #>> ARRAY[t.diagonal_id::text, 'ones_per_period'] FROM settled)::integer AS ones_per_period,-- Black cells in one least period y_k(0 .. P_k - 1).
  calc_diagonals_half_period_value(t.diagonal_id) AS half_period_value,         -- y_k(P_k / 2).
  (SELECT settled #>> ARRAY[NULLIF(t.previous_diagonal,''), 'least_period'] FROM settled)::integer AS previous_least_period,-- P_{k-1}.
  (SELECT settled #>> ARRAY[t.diagonal_id::text, 'doubles'] FROM settled)::integer AS doubles,-- eps_k: 1 when P_k = 2 P_{k-1}.
  (SELECT settled #>> ARRAY[NULLIF(t.previous_diagonal,''), 'doubles'] FROM settled)::integer AS previous_doubles,-- eps_{k-1}.
  (SELECT settled #>> ARRAY[NULLIF(t.previous_diagonal,''), 'previous_doubles'] FROM settled)::integer AS previous_previous_doubles,-- eps_{k-2}.
  (SELECT settled #>> ARRAY[NULLIF(t.previous_diagonal,''), 'ones_per_period'] FROM settled)::integer AS previous_ones_per_period,-- Ones per period of y_{k-1}.
  (SELECT settled #>> ARRAY[NULLIF(t.previous_diagonal,''), 'previous_ones_per_period'] FROM settled)::integer AS previous_previous_ones_per_period,-- Ones per period of y_{k-2}.
  (SELECT settled #>> ARRAY[NULLIF(t.opposite_diagonal,''), 'least_period'] FROM settled)::integer AS opposite_least_period-- P_k of the right diagonal with the same offset.
FROM diagonals t;

-- ----------------------------------------------------------------------------
-- vw_diagonal_period_tests: Is the dyadic d a period of the diagonal, from t = 0 (pure) or from some onset (eventual)?
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_diagonal_period_tests CASCADE;
CREATE VIEW vw_diagonal_period_tests WITH (security_invoker = ON) AS
SELECT
  t.diagonal_period_test_id,                                                    -- <diagonal>-d<period>.
  calc_diagonal_period_tests_name(t.diagonal_period_test_id) AS name,           -- Display alias.
  t.diagonal,                                                                   -- The diagonal.
  t.period,                                                                     -- d, a power of two.
  t.half_cell,                                                                  -- The cell of the diagonal at t = d / 2 (empty before the cone: white).
  calc_diagonal_period_tests_depth(t.diagonal_period_test_id) AS depth,         -- The horizon.
  calc_diagonal_period_tests_diagonal_least_period(t.diagonal_period_test_id) AS diagonal_least_period,-- P_k.
  calc_diagonal_period_tests_diagonal_eventual_period(t.diagonal_period_test_id) AS diagonal_eventual_period,-- Least eventual period.
  calc_diagonal_period_tests_half_cell_value(t.diagonal_period_test_id) AS half_cell_value,-- The diagonal at t = d / 2.
  calc_diagonal_period_tests_half_value(t.diagonal_period_test_id) AS half_value,-- The diagonal at d / 2, white before the cone.
  calc_diagonal_period_tests_comparison_count(t.diagonal_period_test_id) AS comparison_count,-- Comparisons inside the horizon.
  calc_diagonal_period_tests_mismatch_count(t.diagonal_period_test_id) AS mismatch_count,-- Comparisons that differ.
  calc_diagonal_period_tests_last_mismatch_raw(t.diagonal_period_test_id) AS last_mismatch_raw,-- Raw MAXIFS (gap 12); read EventualOnset.
  calc_diagonal_period_tests_ones_in_first_period(t.diagonal_period_test_id) AS ones_in_first_period,-- Black cells among t = 0 .. d - 1.
  calc_diagonal_period_tests_is_pure_period(t.diagonal_period_test_id) AS is_pure_period,-- 1 when every comparison matches and every residue mod d is compared at least once.
  calc_diagonal_period_tests_eventual_onset(t.diagonal_period_test_id) AS eventual_onset,-- The first t from which every comparison matches.
  calc_diagonal_period_tests_is_eventual_period(t.diagonal_period_test_id) AS is_eventual_period,-- 1 when d is a period from the onset on, with the onset in the first half of the horizon and at least 2d matching comparisons after it.
  calc_diagonal_period_tests_is_least(t.diagonal_period_test_id) AS is_least,   -- 1 for the least pure period.
  calc_diagonal_period_tests_is_least_eventual(t.diagonal_period_test_id) AS is_least_eventual,-- 1 for the least eventual period.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.is_pure_period_cache                                                        -- Cached IsPurePeriod from the last fresh compile; read by IsPurePeriod while IsCached = 1.
FROM diagonal_period_tests t;

-- ----------------------------------------------------------------------------
-- vw_diagonal_period_checks: One comparison of a diagonal period test: the diagonal at t against t + d.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_diagonal_period_checks CASCADE;
CREATE VIEW vw_diagonal_period_checks WITH (security_invoker = ON) AS
SELECT
  t.diagonal_period_check_id,                                                   -- <test>-t<time>.
  calc_diagonal_period_checks_name(t.diagonal_period_check_id) AS name,         -- Display alias.
  t.diagonal_period_test,                                                       -- The test.
  t.time,                                                                       -- t.
  t.earlier_cell,                                                               -- The diagonal at t (empty before the cone: white).
  t.later_cell,                                                                 -- The diagonal at t + d.
  calc_diagonal_period_checks_period(t.diagonal_period_check_id) AS period,     -- d.
  calc_diagonal_period_checks_earlier_value(t.diagonal_period_check_id) AS earlier_value,-- At t.
  calc_diagonal_period_checks_later_value(t.diagonal_period_check_id) AS later_value,-- At t + d.
  calc_diagonal_period_checks_earlier_bit(t.diagonal_period_check_id) AS earlier_bit,-- At t, white before the cone.
  calc_diagonal_period_checks_later_bit(t.diagonal_period_check_id) AS later_bit,-- At t + d, white before the cone.
  calc_diagonal_period_checks_is_mismatch(t.diagonal_period_check_id) AS is_mismatch,-- 1 when the diagonal differs at t and t + d.
  calc_diagonal_period_checks_is_in_first_period(t.diagonal_period_check_id) AS is_in_first_period-- 1 for t < d.
FROM diagonal_period_checks t;

-- ----------------------------------------------------------------------------
-- vw_diagonal_facts: One fact a predicate states about one diagonal, decided from the diagonal's computed periods and cells.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_diagonal_facts CASCADE;
CREATE VIEW vw_diagonal_facts WITH (security_invoker = ON) AS
SELECT
  t.diagonal_fact_id,                                                           -- <fact>-<diagonal>.
  calc_diagonal_facts_name(t.diagonal_fact_id) AS name,                         -- Display alias.
  t.fact,                                                                       -- Which fact: all-ones: every cone cell on the edge is black; first-one-at-half: first black cell at t = ceil(k/2), and P_k exceeds that time; balanced: exactly half the cells of one least period are black; doubles: P_k = 2 P_{k-1}; nondecreasing: P_k >= P_{k-1}; repeat-or-double: P_k is P_{k-1} or 2 P_{k-1}; no-triple-double: not (eps_k = eps_{k-1} = eps_{k-2} = 1); half-period-one: y_k(P_k / 2) = 1; eventually-dyadic: w_k has a dyadic eventual period <= min(2^k, 8) inside the horizon; parity-after-doubling: if eps_{k-1} = 1 then eps_k = ones of y_{k-2} per period mod 2; parity-always: eps_k = ones of y_{k-2} per period mod 2; left-half-speed: Pw_k^2 <= P_k (log2 Pw_k <= log2 P_k / 2).
  t.diagonal,                                                                   -- The diagonal.
  calc_diagonal_facts_offset(t.diagonal_fact_id) AS "offset",                   -- k.
  calc_diagonal_facts_ones_count(t.diagonal_fact_id) AS ones_count,             -- Black cells observed.
  calc_diagonal_facts_cell_count(t.diagonal_fact_id) AS cell_count,             -- Cells observed.
  calc_diagonal_facts_first_one_time(t.diagonal_fact_id) AS first_one_time,     -- First black cell.
  calc_diagonal_facts_least_period(t.diagonal_fact_id) AS least_period,         -- P_k.
  calc_diagonal_facts_previous_least_period(t.diagonal_fact_id) AS previous_least_period,-- P_{k-1}.
  calc_diagonal_facts_ones_per_period(t.diagonal_fact_id) AS ones_per_period,   -- Black cells per least period.
  calc_diagonal_facts_half_period_value(t.diagonal_fact_id) AS half_period_value,-- y_k(P_k / 2).
  calc_diagonal_facts_doubles(t.diagonal_fact_id) AS doubles,                   -- eps_k.
  calc_diagonal_facts_previous_doubles(t.diagonal_fact_id) AS previous_doubles, -- eps_{k-1}.
  calc_diagonal_facts_previous_previous_doubles(t.diagonal_fact_id) AS previous_previous_doubles,-- eps_{k-2}.
  calc_diagonal_facts_eventual_period(t.diagonal_fact_id) AS eventual_period,   -- Least dyadic eventual period.
  calc_diagonal_facts_previous_previous_ones_per_period(t.diagonal_fact_id) AS previous_previous_ones_per_period,-- Ones per period of y_{k-2}.
  calc_diagonal_facts_opposite_least_period(t.diagonal_fact_id) AS opposite_least_period,-- P_k of the right diagonal with the same offset.
  calc_diagonal_facts_holds(t.diagonal_fact_id) AS holds,                       -- 1 when the fact holds for this diagonal.
  calc_diagonal_facts_is_decided(t.diagonal_fact_id) AS is_decided,             -- 1 when the horizon certifies the periods the fact needs; otherwise the fact is not an instance.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.holds_cache,                                                                -- Cached Holds from the last fresh compile; read by Holds while IsCached = 1.
  t.is_decided_cache                                                            -- Cached IsDecided from the last fresh compile; read by IsDecided while IsCached = 1.
FROM diagonal_facts t;

-- ----------------------------------------------------------------------------
-- vw_tolerances: Margins epsilon around 1/2 for Problem 2. The limit is 1/2 exactly when, for every epsilon, excursions eventually stop.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tolerances CASCADE;
CREATE VIEW vw_tolerances WITH (security_invoker = ON) AS
SELECT
  t.tolerance_id,                                                               -- eps-<numerator>-<denominator>.
  calc_tolerances_name(t.tolerance_id) AS name,                                 -- Display alias.
  t.epsilon_numerator,                                                          -- Numerator of the margin.
  t.epsilon_denominator,                                                        -- Denominator of the margin. Exact integers, because a float margin and a NUMERIC margin disagree at exact boundaries (docs/toolchain-gaps.md gap 9).
  calc_tolerances_epsilon(t.tolerance_id) AS epsilon,                           -- The margin, for display.
  calc_tolerances_excursion_count(t.tolerance_id) AS excursion_count,           -- Prefixes whose density is more than epsilon from 1/2.
  calc_tolerances_last_excursion_time(t.tolerance_id) AS last_excursion_time,   -- The witness: the last prefix end t outside the margin.
  calc_tolerances_horizon_time(t.tolerance_id) AS horizon_time,                 -- The last prefix checked.
  calc_tolerances_settled_at_horizon(t.tolerance_id) AS settled_at_horizon,     -- Problem 2 instance: 1 when the density at the horizon is within epsilon of 1/2.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.last_excursion_time_cache,                                                  -- Cached LastExcursionTime from the last fresh compile; read by LastExcursionTime while IsCached = 1.
  t.settled_at_horizon_cache                                                    -- Cached SettledAtHorizon from the last fresh compile; read by SettledAtHorizon while IsCached = 1.
FROM tolerances t;

-- ----------------------------------------------------------------------------
-- vw_tolerance_checks: One prefix of the center column against one tolerance: is its density within epsilon of 1/2?
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tolerance_checks CASCADE;
CREATE VIEW vw_tolerance_checks WITH (security_invoker = ON) AS
SELECT
  t.tolerance_check_id,                                                         -- <tolerance>-t<time>.
  calc_tolerance_checks_name(t.tolerance_check_id) AS name,                     -- Display alias.
  t.tolerance,                                                                  -- The margin.
  t.cell,                                                                       -- The center cell ending the prefix.
  calc_tolerance_checks_epsilon_numerator(t.tolerance_check_id) AS epsilon_numerator,-- Numerator of the margin.
  calc_tolerance_checks_epsilon_denominator(t.tolerance_check_id) AS epsilon_denominator,-- Denominator of the margin.
  calc_tolerance_checks_abs_discrepancy(t.tolerance_check_id) AS abs_discrepancy,-- |ones - zeros| of the prefix.
  calc_tolerance_checks_prefix_length(t.tolerance_check_id) AS prefix_length,   -- Terms in the prefix.
  calc_tolerance_checks_time(t.tolerance_check_id) AS time,                     -- Prefix end t.
  calc_tolerance_checks_density_deviation(t.tolerance_check_id) AS density_deviation,-- |density - 1/2| of the prefix.
  calc_tolerance_checks_is_excursion(t.tolerance_check_id) AS is_excursion      -- 1 when the prefix density is more than epsilon from 1/2, in exact integers: |ones - zeros| / N > 2 epsilon.
FROM tolerance_checks t;

-- ----------------------------------------------------------------------------
-- vw_color_counts: How often each color occurs in each column ("does each color of cell occur on average equally often").
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_color_counts CASCADE;
CREATE VIEW vw_color_counts WITH (security_invoker = ON) AS
SELECT
  t.color_count_id,                                                             -- <column>-<color>.
  calc_color_counts_name(t.color_count_id) AS name,                             -- Display alias.
  t."column",                                                                   -- The column.
  t.cell_state,                                                                 -- The color.
  calc_color_counts_depth(t.color_count_id) AS depth,                           -- The horizon.
  calc_color_counts_cone_count(t.color_count_id) AS cone_count,                 -- Computed cells of this column with this color.
  calc_color_counts_column_first_time(t.color_count_id) AS column_first_time,   -- Terms before this are background (white).
  calc_color_counts_occurrence_count(t.color_count_id) AS occurrence_count,     -- Terms 0 .. Depth of this column with this color, counting background terms as white.
  calc_color_counts_share(t.color_count_id) AS share,                           -- Share of terms with this color.
  calc_color_counts_share_deviation(t.color_count_id) AS share_deviation        -- Distance of the share from 1/2.
FROM color_counts t;

-- ----------------------------------------------------------------------------
-- vw_machine_models: What one step of computational effort is: the cost model. Problem 3 needs one fixed; universality relates them only up to simulation overhead.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_machine_models CASCADE;
CREATE VIEW vw_machine_models WITH (security_invoker = ON) AS
SELECT
  t.machine_model_id,                                                           -- Name of the model.
  calc_machine_models_name(t.machine_model_id) AS name,                         -- Display alias.
  t.step_meaning,                                                               -- What one unit of effort counts.
  t.input_encoding,                                                             -- How n is given to the machine.
  calc_machine_models_algorithm_count(t.machine_model_id) AS algorithm_count    -- Algorithms recorded on this model.
FROM machine_models t;

-- ----------------------------------------------------------------------------
-- vw_algorithms: A way of computing c(n) on a machine model. An algorithm that stores the answer is not admissible. Problem 3 asks whether every admissible algorithm's effort ratio effort/n is unbounded. Light-cone simulation costs O(n²) cell updates; beating O(n²) would be a partial result.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_algorithms CASCADE;
CREATE VIEW vw_algorithms WITH (security_invoker = ON) AS
SELECT
  t.algorithm_id,                                                               -- Name of the algorithm.
  calc_algorithms_name(t.algorithm_id) AS name,                                 -- Display alias.
  t.machine_model,                                                              -- The machine model its effort is counted in.
  t.effort_rule,                                                                -- How its effort for n is counted: cone-updates (simulate the light cone) or table-read (one read).
  t.stores_answer,                                                              -- 1 when the machine contains the sequence itself.
  calc_algorithms_is_admissible(t.algorithm_id) AS is_admissible,               -- 1 when the algorithm does not store the answer.
  calc_algorithms_computation_count(t.algorithm_id) AS computation_count,       -- Values of n computed.
  calc_algorithms_wrong_output_count(t.algorithm_id) AS wrong_output_count,     -- Outputs that differ from c(n). Must be 0.
  calc_algorithms_ratio_at_horizon(t.algorithm_id) AS ratio_at_horizon,         -- effort/n at n = depth.
  calc_algorithms_ratio_at_half_horizon(t.algorithm_id) AS ratio_at_half_horizon,-- effort/n at n = depth/2.
  calc_algorithms_is_ratio_growing(t.algorithm_id) AS is_ratio_growing,         -- 1 when effort/n grows between half the horizon and the horizon (no sign of O(n)).
  calc_algorithms_effort_holds(t.algorithm_id) AS effort_holds,                 -- Problem 3 instance: an admissible algorithm shows no sign of O(n) effort (inadmissible ones are excluded, so hold vacuously).
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.effort_holds_cache                                                          -- Cached EffortHolds from the last fresh compile; read by EffortHolds while IsCached = 1.
FROM algorithms t;

-- ----------------------------------------------------------------------------
-- vw_computations: machine[m][n] = {v, t}: one algorithm computing c(n), with its output value and effort.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_computations CASCADE;
CREATE VIEW vw_computations WITH (security_invoker = ON) AS
SELECT
  t.computation_id,                                                             -- <algorithm>-n<n>.
  calc_computations_name(t.computation_id) AS name,                             -- Display alias.
  t.algorithm,                                                                  -- The algorithm m.
  t.time_step,                                                                  -- The target time step n.
  calc_computations_effort_rule(t.computation_id) AS effort_rule,               -- How effort is counted.
  calc_computations_target_index(t.computation_id) AS target_index,             -- n.
  calc_computations_depth(t.computation_id) AS depth,                           -- The horizon.
  calc_computations_center_value(t.computation_id) AS center_value,             -- c(n) in the model.
  calc_computations_cone_updates(t.computation_id) AS cone_updates,             -- Cell updates to reach line n.
  calc_computations_output_value(t.computation_id) AS output_value,             -- v: the value the algorithm outputs (both recorded algorithms read the computed cell).
  calc_computations_is_correct(t.computation_id) AS is_correct,                 -- 1 when v = c(n).
  calc_computations_effort(t.computation_id) AS effort,                         -- t: the effort spent.
  calc_computations_effort_ratio(t.computation_id) AS effort_ratio,             -- effort / n.
  calc_computations_is_horizon(t.computation_id) AS is_horizon,                 -- 1 at n = depth.
  calc_computations_is_half_horizon(t.computation_id) AS is_half_horizon        -- 1 at n = depth/2.
FROM computations t;

-- ----------------------------------------------------------------------------
-- vw_variables: The variables the predicates quantify over, the table whose rows are their values in the model, and whether their domain is infinite in the problem.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_variables CASCADE;
CREATE VIEW vw_variables WITH (security_invoker = ON) AS
SELECT
  t.variable_id,                                                                -- Name of the variable.
  calc_variables_name(t.variable_id) AS name,                                   -- Display alias.
  t.symbol,                                                                     -- How the problem writes it.
  t.meaning,                                                                    -- What it ranges over.
  t.domain_table,                                                               -- The table whose rows are its values in the model (finite there).
  t.is_unbounded_in_problem,                                                    -- 1 when its domain in the problem is infinite.
  calc_variables_binder_count(t.variable_id) AS binder_count                    -- Quantifiers binding it, across all predicates.
FROM variables t;

-- ----------------------------------------------------------------------------
-- vw_operators: The symbols formal statements are built from: binders (quantifiers, limits), connectives, relations, arithmetic and the functions of the model (c, x, rule30, cTail, ...).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_operators CASCADE;
CREATE VIEW vw_operators WITH (security_invoker = ON) AS
SELECT
  t.operator_id,                                                                -- Name of the operator.
  calc_operators_name(t.operator_id) AS name,                                   -- Display alias.
  t.symbol,                                                                     -- How it is written.
  t.kind,                                                                       -- binder, infix, prefix, apply, atom, var or const: how a term with this operator is written out.
  t.arity,                                                                      -- Number of arguments (a binder has two: its condition and its body).
  t.is_modeled,                                                                 -- 1 when the model computes this operator (a table or field gives it its value); 0 when it is only a named symbol so far.
  calc_operators_use_count(t.operator_id) AS use_count                          -- Terms using it.
FROM operators t;

-- ----------------------------------------------------------------------------
-- vw_terms: One node of a formal statement: an operator with its argument terms, a variable, or a constant. A binder holds its bound variable, its condition (Arg1) and its body (Arg2). The text, the quantifier count and whether a quantifier ranges over an infinite domain are computed from the tree.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_terms: One node of a formal statement: an operator with its argument terms, a variable, or a constant. A binder holds its bound variable, its condition (Arg1) and its body (Arg2). The text, the quantifier count and whether a quantifier ranges over an infinite domain are computed from the tree.
-- SELF-REFERENTIAL SETTLE: Terms has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: rendered. Drivers: arg1, arg2, arg3, arg4.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_terms CASCADE;
CREATE VIEW vw_terms WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.term_id, jsonb_build_object(
      'rendered', CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'var' THEN ((SELECT symbol::text FROM variables WHERE variable_id = (SELECT NULLIF(t.variable::text,''))))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'const' THEN (CONCAT('', (SELECT (NULLIF(t.constant::text,''))::integer)))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'atom' THEN ((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'binder' THEN (CONCAT((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '[', (SELECT symbol::text FROM variables WHERE variable_id = (SELECT NULLIF(t.variable::text,''))), ', ', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg1,''), 'rendered')), ', ', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg2,''), 'rendered')), ']'))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'infix' THEN (CONCAT('(', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg1,''), 'rendered')), ' ', (SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), ' ', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg2,''), 'rendered')), ')'))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'prefix' THEN (CONCAT((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg1,''), 'rendered'))))::text ELSE (CONCAT((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '[', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg1,''), 'rendered')), CASE WHEN COALESCE(((SELECT arity::integer FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::NUMERIC, 0) >= 2 THEN (CONCAT(', ', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg2,''), 'rendered'))))::text ELSE ('')::text END, CASE WHEN COALESCE(((SELECT arity::integer FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::NUMERIC, 0) >= 3 THEN (CONCAT(', ', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg3,''), 'rendered'))))::text ELSE ('')::text END, CASE WHEN COALESCE(((SELECT arity::integer FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::NUMERIC, 0) >= 4 THEN (CONCAT(', ', (SELECT jsonb_extract_path_text('{}'::jsonb, NULLIF(t.arg4,''), 'rendered'))))::text ELSE ('')::text END, ']'))::text END)::text END)::text END)::text END)::text END)::text END
    ))
    FROM terms t WHERE NULLIF(t.arg1,'') IS NULL AND NULLIF(t.arg2,'') IS NULL AND NULLIF(t.arg3,'') IS NULL AND NULLIF(t.arg4,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.term_id, jsonb_build_object(
      'rendered', CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'var' THEN ((SELECT symbol::text FROM variables WHERE variable_id = (SELECT NULLIF(t.variable::text,''))))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'const' THEN (CONCAT('', (SELECT (NULLIF(t.constant::text,''))::integer)))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'atom' THEN ((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'binder' THEN (CONCAT((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '[', (SELECT symbol::text FROM variables WHERE variable_id = (SELECT NULLIF(t.variable::text,''))), ', ', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg1,''), 'rendered')), ', ', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg2,''), 'rendered')), ']'))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'infix' THEN (CONCAT('(', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg1,''), 'rendered')), ' ', (SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), ' ', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg2,''), 'rendered')), ')'))::text ELSE (CASE WHEN COALESCE((SELECT kind::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '') = 'prefix' THEN (CONCAT((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg1,''), 'rendered'))))::text ELSE (CONCAT((SELECT symbol::text FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))), '[', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg1,''), 'rendered')), CASE WHEN COALESCE(((SELECT arity::integer FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::NUMERIC, 0) >= 2 THEN (CONCAT(', ', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg2,''), 'rendered'))))::text ELSE ('')::text END, CASE WHEN COALESCE(((SELECT arity::integer FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::NUMERIC, 0) >= 3 THEN (CONCAT(', ', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg3,''), 'rendered'))))::text ELSE ('')::text END, CASE WHEN COALESCE(((SELECT arity::integer FROM operators WHERE operator_id = (SELECT NULLIF(t.term_operator::text,''))))::NUMERIC, 0) >= 4 THEN (CONCAT(', ', (SELECT jsonb_extract_path_text(a.settled, NULLIF(t.arg4,''), 'rendered'))))::text ELSE ('')::text END, ']'))::text END)::text END)::text END)::text END)::text END)::text END
    ))
    FROM terms t
    WHERE NOT (a.settled ? t.term_id) AND NOT (NULLIF(t.arg1,'') IS NULL AND NULLIF(t.arg2,'') IS NULL AND NULLIF(t.arg3,'') IS NULL AND NULLIF(t.arg4,'') IS NULL) AND (NULLIF(t.arg1,'') IS NULL OR a.settled ? t.arg1) AND (NULLIF(t.arg2,'') IS NULL OR a.settled ? t.arg2) AND (NULLIF(t.arg3,'') IS NULL OR a.settled ? t.arg3) AND (NULLIF(t.arg4,'') IS NULL OR a.settled ? t.arg4)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM terms t
    WHERE NOT (a.settled ? t.term_id) AND NOT (NULLIF(t.arg1,'') IS NULL AND NULLIF(t.arg2,'') IS NULL AND NULLIF(t.arg3,'') IS NULL AND NULLIF(t.arg4,'') IS NULL) AND (NULLIF(t.arg1,'') IS NULL OR a.settled ? t.arg1) AND (NULLIF(t.arg2,'') IS NULL OR a.settled ? t.arg2) AND (NULLIF(t.arg3,'') IS NULL OR a.settled ? t.arg3) AND (NULLIF(t.arg4,'') IS NULL OR a.settled ? t.arg4))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.term_id,                                                                    -- <predicate>-<preorder index>.
  calc_terms_name(t.term_id) AS name,                                           -- Display alias.
  t.term_operator,                                                              -- The operator (var and const for leaves).
  t.variable,                                                                   -- The variable of a var leaf, or the variable a binder binds.
  t.constant,                                                                   -- The value of a const leaf.
  t.bounds_variable,                                                            -- On a binder: 1 when its condition gives the variable a finite range (as in Theorem C's t in [T, 2T + p]).
  t.arg1,                                                                       -- First argument (a binder: its condition).
  t.arg2,                                                                       -- Second argument (a binder: its body).
  t.arg3,                                                                       -- Third argument.
  t.arg4,                                                                       -- Fourth argument.
  t.introduced_in_loop,                                                         -- The model-native loop that added this term; empty for the core predicates.
  t.predicate_key,                                                              -- The predicate whose statement this node belongs to (a plain key, not a reference: Predicates already points at the root term).
  calc_terms_op_symbol(t.term_id) AS op_symbol,                                 -- How the operator is written.
  calc_terms_op_kind(t.term_id) AS op_kind,                                     -- How the term is written out.
  calc_terms_op_arity(t.term_id) AS op_arity,                                   -- Number of arguments.
  calc_terms_op_is_modeled(t.term_id) AS op_is_modeled,                         -- 1 when the model computes the operator.
  calc_terms_var_symbol(t.term_id) AS var_symbol,                               -- The variable as written.
  calc_terms_var_unbounded(t.term_id) AS var_unbounded,                         -- 1 when the variable ranges over an infinite domain.
  (SELECT settled #>> ARRAY[NULLIF(t.arg1,''), 'rendered'] FROM settled)::text AS arg1_text,-- Arg1 written out.
  (SELECT settled #>> ARRAY[NULLIF(t.arg2,''), 'rendered'] FROM settled)::text AS arg2_text,-- Arg2 written out.
  (SELECT settled #>> ARRAY[NULLIF(t.arg3,''), 'rendered'] FROM settled)::text AS arg3_text,-- Arg3 written out.
  (SELECT settled #>> ARRAY[NULLIF(t.arg4,''), 'rendered'] FROM settled)::text AS arg4_text,-- Arg4 written out.
  (SELECT settled #>> ARRAY[t.term_id::text, 'rendered'] FROM settled)::text AS rendered,-- The term written out in Wolfram Language style, computed from the tree.
  calc_terms_is_unbounded_binder(t.term_id) AS is_unbounded_binder,             -- 1 for a quantifier over an infinite domain.
  calc_terms_is_binder(t.term_id) AS is_binder,                                 -- 1 for a quantifier (or another binder).
  calc_terms_is_unmodeled_operator(t.term_id) AS is_unmodeled_operator          -- 1 when the model does not compute this operator yet.
FROM terms t;

-- ----------------------------------------------------------------------------
-- vw_predicates: The properties stated about the model: definitions, theorems, bridge obligations and the three prize problems. The formal statement is a Terms tree; its bounded instances are computed from the model; a model-native loop adds its hypotheses here as rows.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_predicates CASCADE;
CREATE VIEW vw_predicates WITH (security_invoker = ON) AS
SELECT
  t.predicate_id,                                                               -- Name of the predicate.
  calc_predicates_name(t.predicate_id) AS name,                                 -- Display alias.
  t.problem,                                                                    -- Definition, Known result, Theorem, Bridge obligation, Hypothesis, or the prize problem it is (P1, P2, P3).
  t.instance_kind,                                                              -- Which reference of PredicateInstances decides an instance.
  t.root_term,                                                                  -- The formal statement.
  t.statement,                                                                  -- A gloss in words; the formal content is the term tree.
  t.instance_meaning,                                                           -- What one bounded instance asserts.
  t.failure_refutes,                                                            -- 1 when a failing instance is a counterexample to the statement; 0 when it only means the horizon did not decide it.
  t.bound_slope,                                                                -- For bound hypotheses: the bound is slope * |a| + intercept.
  t.bound_intercept,                                                            -- For bound hypotheses: see BoundSlope.
  t.domain_min,                                                                 -- For bound hypotheses: the smallest index (N, T) the statement covers.
  t.covers_domain,                                                              -- 1 when the instance rows enumerate the whole bounded domain of the statement, so holding on all of them verifies it; 0 when they are a sample (a model horizon shorter than the statement).
  t.introduced_in_loop,                                                         -- The model-native loop that stated this predicate; empty for the core predicates.
  calc_predicates_formal(t.predicate_id) AS formal,                             -- The formal statement, written out from its term tree.
  calc_predicates_quantifier_count(t.predicate_id) AS quantifier_count,         -- Quantifiers in the statement.
  calc_predicates_unbounded_quantifier_count(t.predicate_id) AS unbounded_quantifier_count,-- Quantifiers over an infinite domain.
  calc_predicates_unmodeled_operator_count(t.predicate_id) AS unmodeled_operator_count,-- Operators of the statement the model does not compute yet.
  calc_predicates_is_computable(t.predicate_id) AS is_computable,               -- 1 when every operator of the statement has a meaning in the model.
  calc_predicates_is_finitely_decidable(t.predicate_id) AS is_finitely_decidable,-- 1 when the model can decide the full statement, not only bounded instances.
  calc_predicates_row_count(t.predicate_id) AS row_count,                       -- Instance rows, in or out of the domain.
  calc_predicates_instance_count(t.predicate_id) AS instance_count,             -- Bounded instances in the domain of the statement.
  calc_predicates_holding_count(t.predicate_id) AS holding_count,               -- Instances that hold.
  calc_predicates_failing_count(t.predicate_id) AS failing_count,               -- Instances that fail.
  calc_predicates_is_refuted(t.predicate_id) AS is_refuted,                     -- 1 when a counterexample instance fails: the statement is false.
  calc_predicates_is_verified(t.predicate_id) AS is_verified,                   -- 1 when the statement is finite, its instances cover its domain and every one holds: the model decides it true.
  calc_predicates_finite_verdict(t.predicate_id) AS finite_verdict,             -- What the model says about the bounded instances.
  calc_predicates_assertion_count(t.predicate_id) AS assertion_count,           -- Ledger claims about this predicate.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.quantifier_count_cache,                                                     -- Cached QuantifierCount from the last fresh compile; read by QuantifierCount while IsCached = 1.
  t.unbounded_quantifier_count_cache,                                           -- Cached UnboundedQuantifierCount from the last fresh compile; read by UnboundedQuantifierCount while IsCached = 1.
  t.unmodeled_operator_count_cache,                                             -- Cached UnmodeledOperatorCount from the last fresh compile; read by UnmodeledOperatorCount while IsCached = 1.
  t.is_finitely_decidable_cache,                                                -- Cached IsFinitelyDecidable from the last fresh compile; read by IsFinitelyDecidable while IsCached = 1.
  t.is_computable_cache,                                                        -- Cached IsComputable from the last fresh compile; read by IsComputable while IsCached = 1.
  t.row_count_cache,                                                            -- Cached RowCount from the last fresh compile; read by RowCount while IsCached = 1.
  t.instance_count_cache,                                                       -- Cached InstanceCount from the last fresh compile; read by InstanceCount while IsCached = 1.
  t.holding_count_cache,                                                        -- Cached HoldingCount from the last fresh compile; read by HoldingCount while IsCached = 1.
  t.failing_count_cache,                                                        -- Cached FailingCount from the last fresh compile; read by FailingCount while IsCached = 1.
  t.is_refuted_cache,                                                           -- Cached IsRefuted from the last fresh compile; read by IsRefuted while IsCached = 1.
  t.is_verified_cache,                                                          -- Cached IsVerified from the last fresh compile; read by IsVerified while IsCached = 1.
  t.finite_verdict_cache                                                        -- Cached FiniteVerdict from the last fresh compile; read by FiniteVerdict while IsCached = 1.
FROM predicates t;

-- ----------------------------------------------------------------------------
-- vw_predicate_instances: One bounded instance of a predicate, pointing at the model row that decides it. This is the roof all predicates share: whether an instance is in the domain, whether it holds and its witness are all read from the model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_predicate_instances CASCADE;
CREATE VIEW vw_predicate_instances WITH (security_invoker = ON) AS
SELECT
  t.predicate_instance_id,                                                      -- <predicate>-<instance>.
  calc_predicate_instances_name(t.predicate_instance_id) AS name,               -- Display alias.
  t.predicate,                                                                  -- The predicate.
  t.introduced_in_loop,                                                         -- The model-native loop that added this instance; empty for the core predicates.
  calc_predicate_instances_instance_kind(t.predicate_instance_id) AS instance_kind,-- Which reference decides it.
  calc_predicate_instances_bound_slope(t.predicate_instance_id) AS bound_slope, -- Bound hypotheses: slope.
  calc_predicate_instances_bound_intercept(t.predicate_instance_id) AS bound_intercept,-- Bound hypotheses: intercept.
  calc_predicate_instances_domain_min(t.predicate_instance_id) AS domain_min,   -- Bound hypotheses: smallest index covered.
  t.rule_table_entry,                                                           -- Deciding row, for a RuleTableEntry instance.
  t.run,                                                                        -- Deciding row, for a Run instance.
  t.period_test,                                                                -- Deciding row, for a PeriodTest instance.
  t.periodicity_candidate,                                                      -- Deciding row, for a PeriodicityCandidate instance.
  t.mismatch_window,                                                            -- Deciding row, for a MismatchWindow instance.
  t.cell,                                                                       -- Deciding row, for a Cell instance.
  t.left_consistency_check,                                                     -- Deciding row, for a LeftConsistencyCheck instance.
  t.tail_candidate,                                                             -- Deciding row, for a TailCandidate instance.
  t.diagonal_period_test,                                                       -- Deciding row, for a DiagonalPeriodTest instance.
  t.diagonal_fact,                                                              -- Deciding row, for a DiagonalFact instance.
  t.accelerator_claim,                                                          -- Deciding row, for a AcceleratorClaim instance.
  t.tolerance,                                                                  -- Deciding row, for a Tolerance instance.
  t.algorithm,                                                                  -- Deciding row, for a Algorithm instance.
  calc_predicate_instances_rule_table_entry_holds(t.predicate_instance_id) AS rule_table_entry_holds,-- RuleTableEntries.MatchesPolynomial.
  calc_predicate_instances_run_holds(t.predicate_instance_id) AS run_holds,     -- Runs.IsLightConeExact.
  calc_predicate_instances_run_setup_holds(t.predicate_instance_id) AS run_setup_holds,-- Runs.IsPrizeSetup.
  calc_predicate_instances_periodicity_candidate_holds(t.predicate_instance_id) AS periodicity_candidate_holds,-- PeriodicityCandidates.IsRefuted.
  calc_predicate_instances_mismatch_window_holds(t.predicate_instance_id) AS mismatch_window_holds,-- MismatchWindows.WindowHolds.
  calc_predicate_instances_cell_holds(t.predicate_instance_id) AS cell_holds,   -- Cells.RunBoundHolds.
  calc_predicate_instances_left_consistency_check_holds(t.predicate_instance_id) AS left_consistency_check_holds,-- LeftConsistencyChecks.IsConsistent.
  calc_predicate_instances_tail_candidate_holds(t.predicate_instance_id) AS tail_candidate_holds,-- TailCandidates.IsKilled.
  calc_predicate_instances_tolerance_holds(t.predicate_instance_id) AS tolerance_holds,-- Tolerances.SettledAtHorizon.
  calc_predicate_instances_algorithm_holds(t.predicate_instance_id) AS algorithm_holds,-- Algorithms.EffortHolds.
  calc_predicate_instances_diagonal_period_test_holds(t.predicate_instance_id) AS diagonal_period_test_holds,-- DiagonalPeriodTests.IsPurePeriod.
  calc_predicate_instances_diagonal_fact_holds(t.predicate_instance_id) AS diagonal_fact_holds,-- DiagonalFacts.Holds.
  calc_predicate_instances_accelerator_claim_holds(t.predicate_instance_id) AS accelerator_claim_holds,-- AcceleratorClaims.IsMatch.
  calc_predicate_instances_period_test_holds(t.predicate_instance_id) AS period_test_holds,-- PeriodTests.BoundedRefutationHolds.
  calc_predicate_instances_period_test_windows_holds(t.predicate_instance_id) AS period_test_windows_holds,-- PeriodTests.WindowsHold.
  calc_predicate_instances_candidate_in_domain(t.predicate_instance_id) AS candidate_in_domain,-- Onset within the bounded form.
  calc_predicate_instances_candidate_witness(t.predicate_instance_id) AS candidate_witness,-- First mismatch at or after the onset.
  calc_predicate_instances_tail_in_domain(t.predicate_instance_id) AS tail_in_domain,-- Nonconstant primitive tail.
  calc_predicate_instances_tail_kill_time(t.predicate_instance_id) AS tail_kill_time,-- When left-consistency kills the tail.
  calc_predicate_instances_tail_kill_excess(t.predicate_instance_id) AS tail_kill_excess,-- Kill time minus onset.
  calc_predicate_instances_tail_word_length(t.predicate_instance_id) AS tail_word_length,-- |a|.
  calc_predicate_instances_cell_discrepancy(t.predicate_instance_id) AS cell_discrepancy,-- Ones minus zeros of the prefix.
  calc_predicate_instances_cell_prefix_length(t.predicate_instance_id) AS cell_prefix_length,-- N.
  calc_predicate_instances_cell_is_center(t.predicate_instance_id) AS cell_is_center,-- 1 on the center column.
  calc_predicate_instances_cell_run_length(t.predicate_instance_id) AS cell_run_length,-- Constant run length so far.
  calc_predicate_instances_cell_run_start(t.predicate_instance_id) AS cell_run_start,-- Start of the constant run.
  calc_predicate_instances_test_longest_agreement(t.predicate_instance_id) AS test_longest_agreement,-- Longest agreement run.
  calc_predicate_instances_fact_is_decided(t.predicate_instance_id) AS fact_is_decided,-- The horizon certifies what the fact needs.
  calc_predicate_instances_in_domain(t.predicate_instance_id) AS in_domain,     -- 1 when the instance lies in the domain the statement quantifies over (computed, not chosen).
  calc_predicate_instances_holds(t.predicate_instance_id) AS holds,             -- 1 when the instance holds, read from its deciding row.
  calc_predicate_instances_witness(t.predicate_instance_id) AS witness,         -- The time step that decides it, where there is one: the refuting mismatch or the kill.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.in_domain_cache,                                                            -- Cached InDomain from the last fresh compile; read by InDomain while IsCached = 1.
  t.holds_cache,                                                                -- Cached Holds from the last fresh compile; read by Holds while IsCached = 1.
  t.witness_cache                                                               -- Cached Witness from the last fresh compile; read by Witness while IsCached = 1.
FROM predicate_instances t;

-- ----------------------------------------------------------------------------
-- vw_accelerator_claims: A value an optimizer outside the rulebook claims for a cell. The rulebook computes the cell itself and decides whether the claim matches.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_accelerator_claims CASCADE;
CREATE VIEW vw_accelerator_claims WITH (security_invoker = ON) AS
SELECT
  t.accelerator_claim_id,                                                       -- <evidence>-<cell>.
  calc_accelerator_claims_name(t.accelerator_claim_id) AS name,                 -- Display alias.
  t.cell,                                                                       -- The cell the claim is about.
  t.source,                                                                     -- The evidence file the claimed value comes from.
  t.claimed_value,                                                              -- The value the optimizer reports.
  calc_accelerator_claims_model_value(t.accelerator_claim_id) AS model_value,   -- The value the model computes for that cell.
  calc_accelerator_claims_is_match(t.accelerator_claim_id) AS is_match,         -- 1 when the optimizer agrees with the model.
  t.is_cached,                                                                  -- 1 when the *Cache fields of this row hold the last fresh compile (filled by loop_tools.build, cleared by every save).
  t.is_match_cache                                                              -- Cached IsMatch from the last fresh compile; read by IsMatch while IsCached = 1.
FROM accelerator_claims t;

-- ----------------------------------------------------------------------------
-- fk_labels_*: display labels for relationship fields (read by the generated API).
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS fk_labels_assertions CASCADE;
CREATE VIEW fk_labels_assertions WITH (security_invoker = ON) AS
SELECT
  t.assertion_id AS __pk,
  CASE WHEN r1.loop_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_loops_name(r1.loop_id)::text, ''), r1.loop_id::text) END AS introduced_in_loop__fk_label,
  CASE WHEN r2.predicate_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_predicates_name(r2.predicate_id)::text, ''), r2.predicate_id::text) END AS predicate__fk_label
FROM assertions t
  LEFT JOIN loops r1 ON r1.loop_id = t.introduced_in_loop
  LEFT JOIN predicates r2 ON r2.predicate_id = t.predicate
;

DROP VIEW IF EXISTS fk_labels_dependencies CASCADE;
CREATE VIEW fk_labels_dependencies WITH (security_invoker = ON) AS
SELECT
  t.dependency_id AS __pk,
  CASE WHEN r1.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r1.assertion_id)::text, ''), r1.assertion_id::text) END AS conclusion__fk_label,
  CASE WHEN r2.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r2.assertion_id)::text, ''), r2.assertion_id::text) END AS premise__fk_label
FROM dependencies t
  LEFT JOIN assertions r1 ON r1.assertion_id = t.conclusion
  LEFT JOIN assertions r2 ON r2.assertion_id = t.premise
;

