  CASE WHEN r2.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r2.assertion_id)::text, ''), r2.assertion_id::text) END AS premise__fk_label
FROM prerequisites t
  LEFT JOIN assessments r1 ON r1.assessment_id = t.conclusion_key
  LEFT JOIN assertions r2 ON r2.assertion_id = t.premise
;

DROP VIEW IF EXISTS fk_labels_assessments CASCADE;
CREATE VIEW fk_labels_assessments WITH (security_invoker = ON) AS
SELECT
  t.assessment_id AS __pk,
  CASE WHEN r1.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r1.assertion_id)::text, ''), r1.assertion_id::text) END AS assertion__fk_label,
  CASE WHEN r2.dashboard_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_dashboards_name(r2.dashboard_id)::text, ''), r2.dashboard_id::text) END AS project_key__fk_label
FROM assessments t
  LEFT JOIN assertions r1 ON r1.assertion_id = t.assertion
  LEFT JOIN dashboards r2 ON r2.dashboard_id = t.project_key
;

