  CASE WHEN r1.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r1.assertion_id)::text, ''), r1.assertion_id::text) END AS assertion__fk_label,
  CASE WHEN r2.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r2.assertion_id)::text, ''), r2.assertion_id::text) END AS replacement__fk_label,
  CASE WHEN r3.loop_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_loops_name(r3.loop_id)::text, ''), r3.loop_id::text) END AS loop__fk_label
FROM revisions t
  LEFT JOIN assertions r1 ON r1.assertion_id = t.assertion
  LEFT JOIN assertions r2 ON r2.assertion_id = t.replacement
  LEFT JOIN loops r3 ON r3.loop_id = t.loop
