DROP VIEW IF EXISTS fk_labels_strategies CASCADE;
CREATE VIEW fk_labels_strategies WITH (security_invoker = ON) AS
SELECT
  t.strategy_id AS __pk,
  CASE WHEN r1.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r1.assertion_id)::text, ''), r1.assertion_id::text) END AS goal__fk_label,
  CASE WHEN r2.assertion_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_assertions_name(r2.assertion_id)::text, ''), r2.assertion_id::text) END AS next_target__fk_label,
  CASE WHEN r3.loop_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_loops_name(r3.loop_id)::text, ''), r3.loop_id::text) END AS updated_in_loop__fk_label,
  CASE WHEN r4.loop_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_loops_name(r4.loop_id)::text, ''), r4.loop_id::text) END AS next_loop__fk_label,
  CASE WHEN r5.dashboard_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_dashboards_name(r5.dashboard_id)::text, ''), r5.dashboard_id::text) END AS project_key__fk_label
FROM strategies t
  LEFT JOIN assertions r1 ON r1.assertion_id = t.goal
  LEFT JOIN assertions r2 ON r2.assertion_id = t.next_target
  LEFT JOIN loops r3 ON r3.loop_id = t.updated_in_loop
  LEFT JOIN loops r4 ON r4.loop_id = t.next_loop
  LEFT JOIN dashboards r5 ON r5.dashboard_id = t.project_key
;

