SELECT
  t.mismatch_window_id AS __pk,
  CASE WHEN r1.period_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_periods_name(r1.period_id)::text, ''), r1.period_id::text) END AS period__fk_label,
  CASE WHEN r2.period_test_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_period_tests_name(r2.period_test_id)::text, ''), r2.period_test_id::text) END AS center_test__fk_label,
  CASE WHEN r3.periodicity_candidate_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_periodicity_candidates_name(r3.periodicity_candidate_id)::text, ''), r3.periodicity_candidate_id::text) END AS center_candidate__fk_label,
  CASE WHEN r4.periodicity_candidate_id IS NULL THEN NULL ELSE COALESCE(NULLIF(calc_periodicity_candidates_name(r4.periodicity_candidate_id)::text, ''), r4.periodicity_candidate_id::text) END AS neighbor_candidate__fk_label
FROM mismatch_windows t
  LEFT JOIN periods r1 ON r1.period_id = t.period
  LEFT JOIN period_tests r2 ON r2.period_test_id = t.center_test
  LEFT JOIN periodicity_candidates r3 ON r3.periodicity_candidate_id = t.center_candidate
  LEFT JOIN periodicity_candidates r4 ON r4.periodicity_candidate_id = t.neighbor_candidate
;

